}

export default function ContactsPage() {
  const t = useTranslations('Contacts.page');
  const router = useRouter();
  const supabase = createClient();
  const { accountRole, user, profile, defaultCurrency } = useAuth();
  const canEdit = useCan('send-messages');
  const canEditSettings = useCan('edit-settings');

  const [contacts, setContacts] = useState<ContactWithTags[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(0);
  const [totalCount, setTotalCount] = useState(0);
  // Tag filter — contacts shown must have ANY of these tags (OR).
  const [selectedTagIds, setSelectedTagIds] = useState<string[]>([]);

  // Modals
  const [formOpen, setFormOpen] = useState(false);
  const [editContact, setEditContact] = useState<Contact | null>(null);
  const [detailOpen, setDetailOpen] = useState(false);
  const [detailContactId, setDetailContactId] = useState<string | null>(null);
  const [customFieldsOpen, setCustomFieldsOpen] = useState(false);
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<Contact | null>(null);
  const [deleting, setDeleting] = useState(false);

  // Bulk selection (page-scoped — only the loaded rows are selectable)
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [bulkDeleteOpen, setBulkDeleteOpen] = useState(false);
  const [bulkReassignOpen, setBulkReassignOpen] = useState(false);

  // All tags for display
  const [tagsMap, setTagsMap] = useState<Record<string, Tag>>({});

  // Guards against out-of-order fetch responses: each fetchContacts run
  // claims a sequence number and only the latest is allowed to commit its
  // results. Without this, rapidly toggling tag filters could let a slower
  // earlier request resolve last and render stale rows.
  const fetchSeq = useRef(0);

  const fetchTags = useCallback(async () => {
    const { data } = await supabase.from('tags').select('*');
    if (data) {
      const map: Record<string, Tag> = {};
      data.forEach((t) => (map[t.id] = t));
      setTagsMap(map);
      // Drop any filter selections whose tag no longer exists (e.g. a tag
      // deleted elsewhere) so it can't linger invisibly in the query.
      setSelectedTagIds((prev) => {
        const pruned = prev.filter((id) => map[id]);
        return pruned.length === prev.length ? prev : pruned;
      });
    }
  }, [supabase]);

  const fetchContacts = useCallback(async () => {
    const seq = ++fetchSeq.current;
    setLoading(true);
    // The visible rows are about to change — drop any selection that
    // referred to the old page/search results so the bulk bar can't
    // act on rows the user can no longer see.
    setSelected(new Set());

    const from = page * PAGE_SIZE;
    const to = from + PAGE_SIZE - 1;
    const term = search.trim();

    let contactRows: Contact[];
    let count: number;

    if (selectedTagIds.length > 0) {
      // Tag filter active — resolve it server-side (join + distinct +
      // windowed total count + pagination) so a tag covering many
      // contacts can't silently truncate the result or overflow an IN
      // clause. See migration 025_filter_contacts_by_tags.
      // p_agent_user_id (migration 125): restrict results to the agent's
      // own contacts when the caller is an agent, NULL = no restriction.
      const { data, error } = await supabase.rpc('filter_contacts_by_tags', {
        p_tag_ids: selectedTagIds,
        p_search: term || null,
        p_limit: PAGE_SIZE,
        p_offset: from,
        p_agent_user_id: accountRole === 'agent' && user?.id ? user.id : null,
      });
      if (seq !== fetchSeq.current) return; // superseded by a newer fetch
      if (error) {
        toast.error(t('toastFailedLoad'));
        setLoading(false);
        return;
      }
      const rows = (data ?? []) as { contact: Contact; total_count: number }[];

      const ids = rows.map((r) => r.contact.id);
      if (ids.length > 0) {
        // Fetch the missing relations that the RPC drops
        const { data: relations } = await supabase
          .from('contacts')
          .select(
            'id, lead_details(*), deals(status, assigned_to, pipeline_stages!deals_stage_id_fkey(name))'
          )
          .in('id', ids)
          .order('created_at', { referencedTable: 'deals', ascending: false });

        const relationMap = new Map((relations ?? []).map((r) => [r.id, r]));
        contactRows = rows.map((r) => ({
          ...r.contact,
          lead_details: relationMap.get(r.contact.id)?.lead_details ?? null,
          deals: relationMap.get(r.contact.id)?.deals ?? [],
        }));
      } else {
        contactRows = [];
      }
      count = rows.length > 0 ? Number(rows[0].total_count) : 0;
    } else if (accountRole === 'agent' && user?.id) {
      // ----------------------------------------------------------------
      // Agent-scoped path: show contacts where this agent is involved.
      //
      // We intentionally do NOT use `conversations!inner` here — that
      // approach only surfaces contacts with an active WhatsApp
      // conversation assigned to the agent, which silently hides:
      //   - leads created manually (no conversation yet)
      //   - leads assigned via deals.assigned_to but with no conversation
      //   - leads imported via CSV before a conversation was opened
      //
      // Correct B2B logic: an agent owns a lead if they are either the
      // original creator (user_id) OR have an open deal assigned to them
      // for that contact. We collect both sets, union them, then page.
      //
      // IMPORTANT: deals.assigned_to stores profiles.id (the profiles
      // table PK), NOT user_id (the auth UUID). Use profile.id here.
      // ----------------------------------------------------------------

      // Step 1: collect contact IDs where agent has a deal assigned.
      // profile.id is the profiles table PK which deals.assigned_to references.
      const profileId = profile?.id;
      const { data: agentDeals } = profileId
        ? await supabase
            .from('deals')
            .select('contact_id')
            .eq('assigned_to', profileId)
            .not('contact_id', 'is', null)
        : { data: [] };

      const dealContactIds = (agentDeals
        ?.map((d) => d.contact_id)
        .filter(Boolean) ?? []) as string[];

      // Step 2: query contacts — either created by agent OR in dealContactIds
      let agentQuery = supabase
        .from('contacts')
        .select(
          '*, lead_details(*), deals(status, assigned_to, pipeline_stages!deals_stage_id_fkey(name))',
          {
            count: 'exact',
          }
        )
        .order('created_at', { ascending: false })
        .order('created_at', { referencedTable: 'deals', ascending: false })
        .range(from, to);

      if (dealContactIds.length > 0) {
        // OR: created by this agent OR assigned a deal to this agent
        agentQuery = agentQuery.or(
          `user_id.eq.${user.id},id.in.(${dealContactIds.join(',')})`
        );
      } else {
        // No deals assigned yet — show only contacts this agent created
        agentQuery = agentQuery.eq('user_id', user.id);
      }

      if (term) {
        const like = `%${term}%`;
        agentQuery = agentQuery.or(
          `name.ilike.${like},phone.ilike.${like},email.ilike.${like}`
        );
      }

      const { data, count: exactCount, error } = await agentQuery;
      if (seq !== fetchSeq.current) return;
      if (error) {
        toast.error(t('toastFailedLoad'));
        setLoading(false);
        return;
      }
      contactRows = (data as unknown as Contact[]) ?? [];
      count = exactCount ?? 0;
    } else {
      // Admin / owner path: see all contacts in the account
      let query = supabase
        .from('contacts')
        .select(
          '*, lead_details(*), deals(status, assigned_to, pipeline_stages!deals_stage_id_fkey(name))',
          {
            count: 'exact',
          }
        )
        .order('created_at', { ascending: false })
        .order('created_at', { referencedTable: 'deals', ascending: false })
        .range(from, to);

      if (term) {
        const like = `%${term}%`;
        query = query.or(
          `name.ilike.${like},phone.ilike.${like},email.ilike.${like}`
        );
      }

      const { data, count: exactCount, error } = await query;
      if (seq !== fetchSeq.current) return;
      if (error) {
        toast.error(t('toastFailedLoad'));
        setLoading(false);
        return;
      }
      contactRows = (data as unknown as Contact[]) ?? [];
      count = exactCount ?? 0;
    }

    setTotalCount(count);

    if (contactRows.length === 0) {
      setContacts([]);
      setLoading(false);
      return;
    }

    // Fetch tags for these contacts
    const contactIds = contactRows.map((c) => c.id);
    const { data: contactTags } = await supabase
      .from('contact_tags')
      .select('contact_id, tag_id')
      .in('contact_id', contactIds);

    const { data: convData } = await supabase
      .from('conversations')
      .select('contact_id, first_unanswered_at, assigned_agent_id')
      .in('contact_id', contactIds);

    // Collect all agent IDs we need profiles for.
    // NOTE: two different ID spaces are in play here:
    //   - conversations.assigned_agent_id stores user_id (auth UUID)
    //   - deals.assigned_to stores profiles.id (profiles table PK)
    // We build separate lookups for each.
    const convAssigneeIds = (convData
      ?.map((c) => c.assigned_agent_id)
      .filter(Boolean) ?? []) as string[];

    // Extract deal assignees (profiles.id) from already-fetched contactRows
    type ContactRowWithDeals = Contact & {
      deals?: { assigned_to?: string | null }[];
    };
    const dealAssigneeProfileIds = (contactRows as ContactRowWithDeals[])
      .flatMap((c) => c.deals?.map((d) => d.assigned_to) ?? [])
      .filter(Boolean) as string[];

    // Map keyed by user_id — for conversation assignee display
    const agentsByUserId: Record<string, { id: string; full_name: string }> =
      {};
    if (convAssigneeIds.length > 0) {
      const { data: convProfiles } = await supabase
        .from('profiles')
        .select('user_id, full_name')
        .in('user_id', convAssigneeIds);
      convProfiles?.forEach((p) => {
        agentsByUserId[p.user_id] = { id: p.user_id, full_name: p.full_name };
      });
    }

    // Map keyed by profiles.id — for deal assignee display
    const agentsByProfileId: Record<string, { id: string; full_name: string }> =
      {};
    if (dealAssigneeProfileIds.length > 0) {
      const { data: dealProfiles } = await supabase
        .from('profiles')
        .select('id, user_id, full_name')
        .in('id', dealAssigneeProfileIds);
      dealProfiles?.forEach((p) => {
        agentsByProfileId[p.id] = { id: p.user_id, full_name: p.full_name };
      });
    }

    if (seq !== fetchSeq.current) return; // superseded by a newer fetch

    const tagsByContact: Record<string, string[]> = {};
    contactTags?.forEach((ct) => {
      if (!tagsByContact[ct.contact_id]) tagsByContact[ct.contact_id] = [];
      tagsByContact[ct.contact_id].push(ct.tag_id);
    });

    const convByContact: Record<
      string,
      { first_unanswered_at: string | null; assigned_agent_id: string | null }
    > = {};
    convData?.forEach((c) => {
      convByContact[c.contact_id] = {
        first_unanswered_at: c.first_unanswered_at,
        assigned_agent_id: c.assigned_agent_id,
      };
    });

    // Build a map of contact_id → deal assignee profiles.id
    const dealAssigneeByContact: Record<string, string | null> = {};
    (contactRows as ContactRowWithDeals[]).forEach((c) => {
      const firstDealWithAssignee = c.deals?.find((d) => d.assigned_to);
      if (firstDealWithAssignee?.assigned_to) {
        dealAssigneeByContact[c.id] = firstDealWithAssignee.assigned_to;
      }
    });

    const enriched: ContactWithTags[] = contactRows.map((c) => {
      const conv = convByContact[c.id];
      // Prefer conversation assignee (real-time, user_id space);
      // fall back to deal assignee (profiles.id space)
      const convAgentId = conv?.assigned_agent_id ?? null;
      const dealProfileId = dealAssigneeByContact[c.id] ?? null;
      const assignee =
        (convAgentId ? agentsByUserId[convAgentId] : null) ??
        (dealProfileId ? agentsByProfileId[dealProfileId] : null) ??
        null;
      return {
        ...c,
        tags: (tagsByContact[c.id] ?? [])
          .map((tid) => tagsMap[tid])
          .filter(Boolean),
        first_unanswered_at: conv?.first_unanswered_at,
        assignee,
      };
    });

    setContacts(enriched);
    setLoading(false);
  }, [
    supabase,
    page,
    search,
    selectedTagIds,
    tagsMap,
    t,
    user,
    profile,
    accountRole,
  ]);

  // Load-once-on-mount-ish data fetches. Each setter inside runs
  // inside an async promise completion (Supabase await), not
  // synchronously in the effect body, so the cascade the lint rule
  // warns about doesn't apply here.
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchTags();
  }, [fetchTags]);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchContacts();
  }, [fetchContacts]);

  function openAddForm() {
    setEditContact(null);
    setFormOpen(true);
  }

  function openDetail(contactId: string) {
    setDetailContactId(contactId);
    setDetailOpen(true);
  }

  function confirmDelete(contact: Contact) {
    setDeleteTarget(contact);
    setDeleteConfirmOpen(true);
  }

  async function handleDelete() {
    if (!deleteTarget) return;
    setDeleting(true);

    const { error } = await supabase
      .from('contacts')
      .delete()
      .eq('id', deleteTarget.id);

    if (error) {
      toast.error(t('toastFailedDelete'));
    } else {
      toast.success(t('toastDeleted'));
      vibrate([50, 100, 50]);
      fetchContacts();
    }

    setDeleting(false);
    setDeleteConfirmOpen(false);
    setDeleteTarget(null);
  }

  const allOnPageSelected =
    contacts.length > 0 && contacts.every((c) => selected.has(c.id));
  const someOnPageSelected = contacts.some((c) => selected.has(c.id));

  function toggleSelectAll() {
    setSelected((prev) => {
      const next = new Set(prev);
      if (allOnPageSelected) {
        contacts.forEach((c) => next.delete(c.id));
      } else {
        contacts.forEach((c) => next.add(c.id));
      }
      return next;
    });
  }

  function toggleSelect(id: string) {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  async function handleBulkDelete() {
    const ids = [...selected];
    if (ids.length === 0) return;
    setDeleting(true);

    const { error } = await supabase.from('contacts').delete().in('id', ids);

    if (error) {
      toast.error(t('toastBulkFailedDelete'));
    } else {
      toast.success(t('toastBulkDeleted', { count: ids.length }));
      setSelected(new Set());
      fetchContacts();
    }

    setDeleting(false);
    setBulkDeleteOpen(false);
  }

  const totalPages = Math.ceil(totalCount / PAGE_SIZE);
  const hasNext = page < totalPages - 1;
  const hasPrev = page > 0;

  // Tag filter helpers. Every change resets to page 0 — the result set
  // shrinks/grows so page N may no longer be valid (mirrors the search box).
  const allTags = Object.values(tagsMap).sort((a, b) =>
    a.name.localeCompare(b.name)
  );
  const hasActiveFilters =
    search.trim().length > 0 || selectedTagIds.length > 0;

  function toggleTagFilter(tagId: string) {
    setSelectedTagIds((prev) =>
      prev.includes(tagId)
        ? prev.filter((id) => id !== tagId)
        : [...prev, tagId]
    );
    setPage(0);
  }

  function clearTagFilters() {
    setSelectedTagIds([]);
    setPage(0);
  }

  return (
    <PullToRefresh>
      <div className="space-y-6">
        {/* Header */}
        <PageHeader
          title="Leads"
          subtitle={`${totalCount} total leads in your pipeline`}
          action={
            <div className="flex items-center gap-2">
              {/* Desktop Actions */}
              {canEditSettings && (
                <Button
                  variant="outline"
                  onClick={() => {
                    window.location.href = '/api/contacts/export';
                  }}
                  className="border-border text-muted-foreground hover:bg-muted hidden rounded-full sm:flex"
                >
                  <Download className="mr-1 size-4" />
                  {t('exportBtn') || 'Export'}
                </Button>
              )}
              {canEditSettings && (
                <Button
                  variant="outline"
                  onClick={() => setCustomFieldsOpen(true)}
                  className="border-border text-muted-foreground hover:bg-muted hidden rounded-full sm:flex"
                >
                  <SlidersHorizontal className="mr-1 size-4" />
                  {t('customFieldsBtn')}
                </Button>
              )}
              <GatedButton
                variant="outline"
                canAct={canEditSettings}
                gateReason="add or import contacts"
                onClick={() => router.push('/contacts/import')}
                className="border-border text-muted-foreground hover:bg-muted hidden rounded-full sm:flex"
              >
                <Upload className="mr-1 size-4" />
                {t('importBtn')}
              </GatedButton>

              {/* Mobile Actions Dropdown */}
              {canEditSettings && (
                <div className="flex sm:hidden">
                  <DropdownMenu>
                    <DropdownMenuTrigger className="border-border text-muted-foreground hover:bg-muted focus-visible:ring-ring flex h-9 w-9 items-center justify-center rounded-full border bg-transparent shadow-sm focus-visible:ring-1 focus-visible:outline-none">
                      <MoreVertical className="size-4" />
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      <DropdownMenuItem
                        onClick={() => {
                          window.location.href = '/api/contacts/export';
                        }}
                      >
                        <Download className="mr-2 size-4" />
                        {t('exportBtn') || 'Export'}
                      </DropdownMenuItem>
                      <DropdownMenuItem
                        onClick={() => setCustomFieldsOpen(true)}
                      >
                        <SlidersHorizontal className="mr-2 size-4" />
                        {t('customFieldsBtn')}
                      </DropdownMenuItem>
                      <DropdownMenuItem
                        onClick={() => router.push('/contacts/import')}
                      >
                        <Upload className="mr-2 size-4" />
                        {t('importBtn')}
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>
              )}

              <GatedButton
                canAct={canEdit}
                gateReason="add or import contacts"
                onClick={openAddForm}
                className="bg-primary text-primary-foreground hover:bg-primary/90 rounded-full px-4 py-2 text-sm font-medium shadow-sm"
              >
                <Plus className="size-4 sm:mr-1" />
                <span className="hidden sm:inline">{t('addContactBtn')}</span>
              </GatedButton>
            </div>
          }
        />

        {/* Search + tag filter */}
        <div className="bg-background/95 sticky top-0 z-10 -mx-4 space-y-2 px-4 py-2 backdrop-blur sm:static sm:mx-0 sm:bg-transparent sm:px-0 sm:py-0">
          <div className="mb-4 flex items-center gap-3">
            <div className="relative max-w-sm flex-1">
              <Search className="text-muted-foreground absolute top-1/2 left-3 size-4 -translate-y-1/2" />
              <Input
                value={search}
                onChange={(e) => {
                  setSearch(e.target.value);
                  setPage(0);
                }}
                placeholder="Search leads..."
                className="border-border bg-card placeholder:text-muted-foreground focus:ring-primary/30 w-full rounded-lg border py-1.5 pr-3 pl-9 text-sm focus:ring-2 focus:outline-none"
              />
            </div>

            <Popover>
              <PopoverTrigger
                render={
                  <Button
                    variant="outline"
                    className="border-border text-muted-foreground hover:bg-muted shrink-0"
                  />
                }
              >
                <Filter className="size-4" />
                {t('filterByTags')}
                {selectedTagIds.length > 0 && (
                  <span className="bg-primary text-primary-foreground ml-1 inline-flex items-center justify-center rounded-full px-1.5 text-[10px] font-semibold">
                    {selectedTagIds.length}
                  </span>
                )}
              </PopoverTrigger>
              <PopoverContent align="start" className="w-64 p-0">
                <div className="border-border flex items-center justify-between border-b px-3 py-2">
                  <span className="text-popover-foreground text-sm font-medium">
                    {t('filterByTags')}
                  </span>
                  {selectedTagIds.length > 0 && (
                    <button
                      onClick={clearTagFilters}
                      className="text-muted-foreground hover:text-foreground text-xs"
                    >
                      {t('clearAll')}
                    </button>
                  )}
                </div>
                {allTags.length === 0 ? (
                  <p className="text-muted-foreground px-3 py-4 text-center text-sm">
                    {t('noTagsYet')}
                  </p>
                ) : (
                  <div className="max-h-64 overflow-y-auto py-1">
                    {allTags.map((tag) => (
                      <label
                        key={tag.id}
                        className="hover:bg-muted/50 flex cursor-pointer items-center gap-2.5 px-3 py-1.5"
                      >
                        <Checkbox
                          checked={selectedTagIds.includes(tag.id)}
                          onCheckedChange={() => toggleTagFilter(tag.id)}
                          aria-label={`Filter by ${tag.name}`}
                        />
                        <span
                          className="size-2.5 shrink-0 rounded-full"
                          style={{ backgroundColor: tag.color }}
                        />
                        <span className="text-popover-foreground truncate text-sm">
                          {tag.name}
                        </span>
                      </label>
                    ))}
                  </div>
                )}
              </PopoverContent>
            </Popover>
          </div>

          {/* Active tag-filter chips */}
          {selectedTagIds.length > 0 && (
            <div className="flex flex-wrap items-center gap-1.5">
              {selectedTagIds.map((id) => {
                const tag = tagsMap[id];
                if (!tag) return null;
                return (
                  <span
                    key={id}
                    className="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[11px] font-medium"
                    style={{
                      backgroundColor: tag.color + '20',
                      color: tag.color,
                    }}
                  >
                    {tag.name}
                    <button
                      onClick={() => toggleTagFilter(id)}
                      aria-label={`Remove ${tag.name} filter`}
                      className="hover:opacity-70"
                    >
                      <X className="size-3" />
                    </button>
                  </span>
                );
              })}
              <button
                onClick={clearTagFilters}
                className="text-muted-foreground hover:text-foreground px-1 text-xs"
              >
                {t('clearAll')}
              </button>
            </div>
          )}
        </div>

        {/* Bulk action bar */}
        {selected.size > 0 && (
          <div className="border-border bg-muted/40 flex items-center justify-between gap-4 rounded-lg border px-4 py-2">
            <p className="text-foreground text-sm">
              {t('selectedCount', { count: selected.size })}
            </p>
            <div className="flex items-center gap-2">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setSelected(new Set())}
                className="text-muted-foreground hover:text-foreground"
              >
                {t('clearSelection')}
              </Button>
              <GatedButton
                variant="destructive"
                size="sm"
                canAct={canEdit}
                gateReason="delete contacts"
                onClick={() => setBulkDeleteOpen(true)}
              >
                <Trash2 className="size-4" />
                {t('deleteSelected')}
              </GatedButton>
              <GatedButton
                variant="outline"
                size="sm"
                canAct={canEditSettings}
                gateReason="reassign contacts"
                onClick={() => setBulkReassignOpen(true)}
              >
                Reassign
              </GatedButton>
            </div>
          </div>
        )}

        <BulkReassignModal
          open={bulkReassignOpen}
          onOpenChange={setBulkReassignOpen}
          selectedIds={[...selected]}
          onSuccess={() => {
            setSelected(new Set());
            fetchContacts();
          }}
        />

        {/* Mobile List View */}
        <div className="space-y-3 md:hidden">
          {loading ? (
            <div className="flex flex-col gap-3 py-4">
              {Array.from({ length: 5 }).map((_, i) => (
                <div key={i} className="flex items-center gap-3">
                  <Skeleton className="h-10 w-10 rounded-full" />
                  <div className="flex-1 space-y-2">
                    <Skeleton className="h-4 w-[60%]" />
                    <Skeleton className="h-3 w-[40%]" />
                  </div>
                </div>
              ))}
            </div>
          ) : contacts.length === 0 ? (
            <div className="flex flex-col items-center gap-2 py-12">
              <Users className="text-muted-foreground size-8" />
              <p className="text-muted-foreground text-sm">
                {hasActiveFilters ? t('noContactsMatch') : t('noContactsYet')}
              </p>
              {!hasActiveFilters && (
                <GatedButton
                  canAct={canEdit}
                  gateReason="add or import contacts"
                  variant="outline"
                  size="sm"
                  onClick={openAddForm}
                  className="border-border text-muted-foreground hover:bg-muted mt-2"
                >
                  <Plus className="size-3.5" />
                  {t('addFirstContact')}
                </GatedButton>
              )}
            </div>
          ) : (
            contacts.map((contact) => (
              <div
                key={contact.id}
                className="border-border bg-card relative overflow-hidden rounded-lg border"
              >
                <div
                  className="flex w-full snap-x snap-mandatory overflow-x-auto [&::-webkit-scrollbar]:hidden"
                  style={{ scrollbarWidth: 'none' }}
                >
                  {/* Main Content */}
                  <div
                    className="bg-card flex w-full flex-none cursor-pointer snap-start items-center gap-3 p-3"
                    onClick={() => openDetail(contact.id)}
                  >
                    <Checkbox
                      checked={selected.has(contact.id)}
                      onCheckedChange={() => toggleSelect(contact.id)}
                      onClick={(e) => e.stopPropagation()}
                      aria-label={`Select ${contact.name || contact.phone}`}
                    />
                    <div className="bg-muted border-border flex size-10 shrink-0 items-center justify-center rounded-full border">
                      <span className="text-primary text-xs font-medium">
                        {(contact.name || '?').charAt(0).toUpperCase()}
                      </span>
                    </div>
                    <div className="min-w-0 flex-1">
                      <p className="text-foreground truncate text-sm font-medium">
                        {contact.name || (
                          <span className="text-muted-foreground italic">
                            {t('unnamed')}
                          </span>
                        )}
                      </p>
                      <p className="text-muted-foreground truncate text-xs">
                        {contact.phone}
                      </p>
                      {contact.tags && contact.tags.length > 0 && (
                        <div className="mt-1.5 flex flex-wrap gap-1">
                          {contact.tags.slice(0, 3).map((tag) => (
                            <span
                              key={tag.id}
                              className="inline-flex items-center rounded-full px-1.5 py-0.5 text-[9px] font-medium"
                              style={{
                                backgroundColor: tag.color + '20',
                                color: tag.color,
                              }}
                            >
                              {tag.name}
                            </span>
                          ))}
                        </div>
                      )}
                    </div>
                    <div className="mt-1 flex flex-col items-start gap-1">
                      {contact.first_unanswered_at && (
                        <SlaBadge
                          firstUnansweredAt={contact.first_unanswered_at}
                        />
                      )}
                      {contact.assignee && (
                        <span className="text-muted-foreground bg-muted border-border inline-flex items-center rounded border px-1.5 py-0.5 text-[10px]">
                          {contact.assignee.full_name}
                        </span>
                      )}
                    </div>
                  </div>
                  {/* Swipe Actions */}
                  <div className="divide-border flex flex-none snap-end divide-x">
                    <button
                      onClick={() => openDetail(contact.id)}
                      className="bg-muted hover:bg-muted/80 flex items-center justify-center px-4 transition-colors"
                      aria-label="View details"
                    >
                      <ExternalLink className="text-foreground size-4" />
                    </button>
                    <button
                      onClick={() => confirmDelete(contact)}
                      className="bg-destructive/10 hover:bg-destructive/20 flex items-center justify-center px-4 transition-colors"
                      aria-label={t('deleteAction')}
                    >
                      <Trash2 className="text-destructive size-4" />
                    </button>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Desktop Table View */}
        <div className="border-border hidden overflow-hidden rounded-lg border md:block">
          <Table>
            <TableHeader>
              <TableRow className="border-border hover:bg-transparent">
                <TableHead className="w-10">
                  <Checkbox
                    checked={allOnPageSelected}
                    indeterminate={!allOnPageSelected && someOnPageSelected}
                    onCheckedChange={toggleSelectAll}
                    disabled={contacts.length === 0}
                    aria-label={t('selectAllOnPage')}
                  />
                </TableHead>
                <TableHead className="text-muted-foreground font-medium">
                  LEAD
                </TableHead>
                <TableHead className="text-muted-foreground hidden font-medium md:table-cell">
                  SOURCE
                </TableHead>
                <TableHead className="text-muted-foreground hidden font-medium md:table-cell">
                  LOCATION
                </TableHead>
                <TableHead className="text-muted-foreground hidden font-medium md:table-cell">
                  BUDGET
                </TableHead>
                <TableHead className="text-muted-foreground hidden font-medium lg:table-cell">
                  STATUS
                </TableHead>
                <TableHead className="text-muted-foreground hidden font-medium md:table-cell">
                  SLA
                </TableHead>
                <TableHead className="text-muted-foreground hidden font-medium md:table-cell">
                  ASSIGNEE
                </TableHead>
                <TableHead className="text-muted-foreground hidden font-medium md:table-cell">
                  TAGS
                </TableHead>
                <TableHead className="text-muted-foreground hidden font-medium lg:table-cell">
                  UPDATED
                </TableHead>
                <TableHead className="text-muted-foreground hidden font-medium lg:table-cell">
                  CREATED
                </TableHead>
                <TableHead className="text-muted-foreground w-[100px] font-medium">
                  ACTIONS
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                Array.from({ length: 10 }).map((_, i) => (
                  <TableRow key={i} className="border-border">
                    <TableCell className="w-10">
                      <Skeleton className="h-4 w-4" />
                    </TableCell>
                    <TableCell>
                      <Skeleton className="h-5 w-[150px]" />
                    </TableCell>
                    <TableCell className="hidden md:table-cell">
                      <Skeleton className="h-4 w-[120px]" />
                    </TableCell>
                    <TableCell className="hidden xl:table-cell">
                      <Skeleton className="h-5 w-[100px]" />
                    </TableCell>
                    <TableCell className="hidden xl:table-cell">
                      <Skeleton className="h-5 w-[100px]" />
                    </TableCell>
                    <TableCell className="hidden md:table-cell">
                      <Skeleton className="h-5 w-16" />
                    </TableCell>
                    <TableCell className="hidden md:table-cell">
                      <Skeleton className="h-5 w-20" />
                    </TableCell>
                    <TableCell className="hidden md:table-cell">
                      <Skeleton className="h-5 w-[120px]" />
                    </TableCell>
                    <TableCell className="hidden lg:table-cell">
                      <Skeleton className="h-4 w-[100px]" />
                    </TableCell>
                    <TableCell className="hidden lg:table-cell">
                      <Skeleton className="h-4 w-[100px]" />
                    </TableCell>
                    <TableCell className="hidden lg:table-cell">
                      <Skeleton className="h-4 w-[100px]" />
                    </TableCell>
                    <TableCell />
                  </TableRow>
                ))
              ) : contacts.length === 0 ? (
                <TableRow className="border-border">
                  <TableCell colSpan={12} className="py-12 text-center">
                    <div className="flex flex-col items-center gap-2">
                      <Users className="text-muted-foreground size-8" />
                      <p className="text-muted-foreground text-sm">
                        {hasActiveFilters
                          ? t('noContactsMatch')
                          : t('noContactsYet')}
                      </p>
                      {!hasActiveFilters && (
                        <GatedButton
                          canAct={canEdit}
                          gateReason="add or import contacts"
                          variant="outline"
                          size="sm"
                          onClick={openAddForm}
                          className="border-border text-muted-foreground hover:bg-muted mt-2"
                        >
                          <Plus className="size-3.5" />
                          {t('addFirstContact')}
                        </GatedButton>
                      )}
                    </div>
                  </TableCell>
                </TableRow>
              ) : (
                contacts.map((contact) => (
                  <TableRow
                    key={contact.id}
                    className="border-border hover:bg-muted/50 cursor-pointer"
                    onClick={() => openDetail(contact.id)}
                  >
                    <TableCell onClick={(e) => e.stopPropagation()}>
                      <Checkbox
                        checked={selected.has(contact.id)}
                        onCheckedChange={() => toggleSelect(contact.id)}
                        aria-label={`Select ${contact.name || contact.phone}`}
                      />
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-3">
                        <Avatar className="h-9 w-9 shrink-0">
                          <AvatarFallback
                            className="text-sm font-medium text-white"
                            style={{
                              background: avatarColorForName(contact.name),
                            }}
                          >
                            {initialsForName(contact.name)}
                          </AvatarFallback>
                        </Avatar>
                        <div className="min-w-0 flex-1">
                          <p className="text-foreground truncate text-sm font-medium">
                            {contact.name || 'Unknown'}
                          </p>
                          <p className="text-muted-foreground truncate text-xs">
                            {contact.phone}
                          </p>
                        </div>
                      </div>
                    </TableCell>
                    <TableCell className="hidden md:table-cell">
                      {contact.lead_details?.source ? (
                        <SourceBadge source={contact.lead_details.source} />
                      ) : (
                        <span className="text-muted-foreground text-xs">-</span>
                      )}
                    </TableCell>
                    <TableCell className="text-foreground hidden text-sm md:table-cell">
                      {contact.lead_details?.location_preference || '-'}
                    </TableCell>
                    <TableCell className="text-foreground hidden text-sm md:table-cell">
                      {(() => {
                        const min = contact.lead_details?.budget_min;
                        const max = contact.lead_details?.budget_max;
                        if (!min && !max) return '-';

                        const format = (v: number) =>
                          defaultCurrency === 'INR'
                            ? formatINR(v)
                            : formatCurrency(v, defaultCurrency);

                        if (min && !max) return format(min);
                        if (!min && max) return format(max);
                        return `${format(min as number)} - ${format(max as number)}`;
                      })()}
                    </TableCell>
                    <TableCell className="hidden lg:table-cell">
                      {contact.deals &&
                      contact.deals.length > 0 &&
                      contact.deals[0]?.pipeline_stages?.name ? (
                        <StatusBadge
                          status={contact.deals[0].pipeline_stages.name}
                        />
                      ) : (
                        <span className="text-muted-foreground text-xs">-</span>
                      )}
                    </TableCell>
                    <TableCell className="hidden md:table-cell">
                      {contact.first_unanswered_at ? (
                        <SlaBadge
                          firstUnansweredAt={contact.first_unanswered_at}
                        />
                      ) : (
                        <span className="text-muted-foreground text-xs">-</span>
                      )}
                    </TableCell>
                    <TableCell className="hidden md:table-cell">
                      {contact.assignee ? (
                        <span className="text-muted-foreground bg-muted border-border inline-flex items-center rounded border px-2 py-1 text-xs">
                          {contact.assignee.full_name}
                        </span>
                      ) : (
                        <span className="text-muted-foreground text-xs">-</span>
                      )}
                    </TableCell>
                    <TableCell className="hidden md:table-cell">
                      <div className="flex flex-wrap gap-1">
                        {contact.tags && contact.tags.length > 0 ? (
                          contact.tags.slice(0, 3).map((tag) => (
                            <span
                              key={tag.id}
                              className="inline-flex items-center rounded-full px-2 py-0.5 text-[10px] font-medium"
                              style={{
                                backgroundColor: tag.color + '20',
                                color: tag.color,
                              }}
                            >
                              {tag.name}
                            </span>
                          ))
                        ) : (
                          <span className="text-muted-foreground text-xs">
                            -
                          </span>
                        )}
                        {contact.tags && contact.tags.length > 3 && (
                          <span className="text-muted-foreground text-[10px]">
                            +{contact.tags.length - 3}
                          </span>
                        )}
                      </div>
                    </TableCell>
                    <TableCell className="text-muted-foreground hidden text-xs lg:table-cell">
                      {formatRelativeDate(contact.updated_at)}
                    </TableCell>
                    <TableCell className="text-muted-foreground hidden text-xs lg:table-cell">
                      {new Date(contact.created_at).toLocaleDateString(
                        'en-US',
                        {
                          month: 'short',
                          day: 'numeric',
                          year: 'numeric',
                        }
                      )}
                    </TableCell>
                    <TableCell onClick={(e) => e.stopPropagation()}>
                      <div className="flex items-center gap-1">
                        <Link
                          href={`/inbox?contact=${contact.id}`}
                          className="hover:bg-muted text-muted-foreground hover:text-foreground rounded-lg p-1.5"
                          onClick={(e) => e.stopPropagation()}
                          title="Open in Inbox"
                        >
                          <MessageCircle className="size-4" />
                        </Link>
                        <button
                          className="hover:bg-muted text-muted-foreground hover:text-foreground rounded-lg p-1.5"
                          title="Edit lead"
                          onClick={(e) => {
                            e.stopPropagation();
                            openDetail(contact.id);
                          }}
                        >
                          <Pencil className="size-4" />
                        </button>
                        <DropdownMenu>
                          <DropdownMenuTrigger
                            className="hover:bg-muted text-muted-foreground hover:text-foreground rounded-lg p-1.5"
                            onClick={(e) => e.stopPropagation()}
                          >
                            <MoreHorizontal className="size-4" />
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem
                              onClick={(e) => {
                                e.stopPropagation();
                                openDetail(contact.id);
                              }}
                            >
                              <ExternalLink className="mr-2 size-4" />
                              View Details
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem
                              className="text-destructive focus:text-destructive"
                              onClick={(e) => {
                                e.stopPropagation();
                                confirmDelete(contact);
                              }}
                            >
                              <Trash2 className="mr-2 size-4" />
                              Delete Lead
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </div>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </div>

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="flex items-center justify-between">
            <p className="text-muted-foreground text-xs">
              {t('showingPagination', {
                start: page * PAGE_SIZE + 1,
                end: Math.min((page + 1) * PAGE_SIZE, totalCount),
                total: totalCount,
              })}
            </p>
            <div className="flex items-center gap-1">
              <Button
                variant="outline"
                size="icon-sm"
                disabled={!hasPrev}
                onClick={() => setPage((p) => p - 1)}
                className="border-border text-muted-foreground hover:bg-muted hover:text-foreground disabled:opacity-30"
              >
                <ChevronLeft className="size-4" />
              </Button>
              <span className="text-muted-foreground px-2 text-xs">
                {t('pageCount', { page: page + 1, total: totalPages })}
              </span>
              <Button
                variant="outline"
                size="icon-sm"
                disabled={!hasNext}
                onClick={() => setPage((p) => p + 1)}
                className="border-border text-muted-foreground hover:bg-muted hover:text-foreground disabled:opacity-30"
              >
                <ChevronRight className="size-4" />
              </Button>
            </div>
          </div>
        )}

        {/* Contact Form Dialog — used only for new lead creation */}
        <ContactForm
          open={formOpen}
          onOpenChange={setFormOpen}
          contact={editContact}
          contactTags={[]}
          onSaved={() => {
            fetchContacts();
            fetchTags();
          }}
          onViewExisting={(id) => {
            setFormOpen(false);
            openDetail(id);
          }}
        />

        {/* Contact Detail Sheet */}
        <ContactDetailView
          open={detailOpen}
          onOpenChange={setDetailOpen}
          contactId={detailContactId}
          onUpdated={fetchContacts}
        />

        {/* Custom Fields Manager (admin+) */}
        {canEditSettings && (
          <CustomFieldsManager
            open={customFieldsOpen}
            onOpenChange={setCustomFieldsOpen}
          />
        )}

        {/* Delete Confirmation */}
        <Dialog open={deleteConfirmOpen} onOpenChange={setDeleteConfirmOpen}>
          <DialogContent className="bg-popover border-border text-popover-foreground sm:max-w-sm">
            <DialogHeader>
              <DialogTitle className="text-popover-foreground">
                {t('deleteContactTitle')}
              </DialogTitle>
              <DialogDescription className="text-muted-foreground">
                {t('deleteContactDesc', {
                  name: deleteTarget?.name || deleteTarget?.phone || '',
                })}
              </DialogDescription>
            </DialogHeader>
            <DialogFooter className="bg-popover border-border">
              <Button
                variant="outline"
                onClick={() => setDeleteConfirmOpen(false)}
                className="border-border text-muted-foreground hover:bg-muted"
              >
                {t('cancel')}
              </Button>
              <Button
                variant="destructive"
                onClick={handleDelete}
                disabled={deleting}
              >
                {deleting && <Loader2 className="size-4 animate-spin" />}
                {t('deleteBtn')}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>

        {/* Bulk Delete Confirmation */}
        <Dialog open={bulkDeleteOpen} onOpenChange={setBulkDeleteOpen}>
          <DialogContent className="bg-popover border-border text-popover-foreground sm:max-w-sm">
            <DialogHeader>
              <DialogTitle className="text-popover-foreground">
                {t('deleteBulkTitle')}
              </DialogTitle>
              <DialogDescription className="text-muted-foreground">
                {t('deleteBulkDesc', { count: selected.size })}
              </DialogDescription>
            </DialogHeader>
            <DialogFooter className="bg-popover border-border">
              <Button
                variant="outline"
                onClick={() => setBulkDeleteOpen(false)}
                className="border-border text-muted-foreground hover:bg-muted"
              >
                {t('cancel')}
              </Button>
              <Button
                variant="destructive"
                onClick={handleBulkDelete}
                disabled={deleting}
              >
                {deleting && <Loader2 className="size-4 animate-spin" />}
                {t('deleteBtn')}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </div>
    </PullToRefresh>
  );
}

'use client';

import { useCallback, useEffect, useState } from 'react';
import { createClient } from '@/lib/supabase/client';
import { useAuth } from '@/hooks/use-auth';
import { formatCurrency, formatINR } from '@/lib/currency';
import { MessageCircle, Phone, ArrowUpRight } from 'lucide-react';
import Link from 'next/link';

import {
  loadActivity,
  loadConversationsSeries,
  loadMetrics,
  loadPipelineDonut,
  loadResponseTime,
  getFollowupsDueCount,
} from '@/lib/dashboard/queries';
import type {
  ActivityItem,
  ConversationsSeriesPoint,
  MetricsBundle,
  PipelineDonutData,
  ResponseTimeSummary,
} from '@/lib/dashboard/types';

import { PageHeader } from '@/components/layout/page-header';
import { SkeletonCard } from '@/components/dashboard/skeleton';
import { TasksWidget } from '@/components/dashboard/tasks-widget';
import { QuickActions } from '@/components/dashboard/quick-actions';
import { ConversationsChart } from '@/components/dashboard/conversations-chart';
import { PipelineDonut } from '@/components/dashboard/pipeline-donut';
import { ResponseTimeChart } from '@/components/dashboard/response-time-chart';
import { ActivityFeed } from '@/components/dashboard/activity-feed';
import { WhatsappSetupChecklist } from '@/components/onboarding/whatsapp-setup-checklist';
import { TeamSetupChecklist } from '@/components/onboarding/team-setup-checklist';
import { SourceBadge } from '@/components/ui/source-badge';
import { StatusBadge } from '@/components/ui/status-badge';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { avatarColorForName, initialsForName } from '@/lib/avatar-color';
import { cn } from '@/lib/utils';
import { useTranslations } from 'next-intl';

type RangeDays = 7 | 30 | 90;

interface DashboardLead {
  id: string;
  name?: string;
  phone?: string;
  contact_tags?: { tags?: { name?: string } }[];
  lead_details?: {
    location_preference?: string;
    budget_min?: number;
    budget_max?: number;
    source?: string;
  } | null;
  deals?: { pipeline_stages?: { name?: string } }[];
}

interface DashboardVisit {
  id: string;
  scheduled_at: string;
  status: string;
  contacts?: { name?: string };
  properties?: { title?: string };
}

export default function DashboardPage() {
  const t = useTranslations('Dashboard.page');
  const { defaultCurrency, profile } = useAuth();

  const [metrics, setMetrics] = useState<MetricsBundle | null>(null);
  const [metricsLoading, setMetricsLoading] = useState(true);

  const [followups, setFollowups] = useState<{
    count: number;
    overdue: number;
  } | null>(null);
  const [followupsLoading, setFollowupsLoading] = useState(true);

  const [range, setRange] = useState<RangeDays>(30);
  const [series, setSeries] = useState<
    Record<RangeDays, ConversationsSeriesPoint[] | null>
  >({
    7: null,
    30: null,
    90: null,
  });
  const [seriesLoading, setSeriesLoading] = useState(true);

  const [pipeline, setPipeline] = useState<PipelineDonutData | null>(null);
  const [pipelineLoading, setPipelineLoading] = useState(true);

  const [responseTime, setResponseTime] = useState<ResponseTimeSummary | null>(
    null
  );
  const [responseTimeLoading, setResponseTimeLoading] = useState(true);

  const [activity, setActivity] = useState<ActivityItem[] | null>(null);
  const [activityLoading, setActivityLoading] = useState(true);

  const [recentLeads, setRecentLeads] = useState<DashboardLead[]>([]);
  const [recentLeadsLoading, setRecentLeadsLoading] = useState(true);

  const [todayVisits, setTodayVisits] = useState<DashboardVisit[]>([]);
  const [todayVisitsLoading, setTodayVisitsLoading] = useState(true);

  const loadAll = useCallback(() => {
    const db = createClient();

    void loadMetrics(db)
      .then((m) => setMetrics(m))
      .catch((err) => console.error('[dashboard] metrics failed:', err))
      .finally(() => setMetricsLoading(false));

    void getFollowupsDueCount(db)
      .then((f) => setFollowups(f))
      .catch((err) => console.error('[dashboard] followups failed:', err))
      .finally(() => setFollowupsLoading(false));

    void loadConversationsSeries(db, 30)
      .then((s) => setSeries((prev) => ({ ...prev, 30: s })))
      .catch((err) => console.error('[dashboard] series failed:', err))
      .finally(() => setSeriesLoading(false));

    void loadPipelineDonut(db)
      .then((p) => setPipeline(p))
      .catch((err) => console.error('[dashboard] pipeline failed:', err))
      .finally(() => setPipelineLoading(false));

    void loadResponseTime(db)
      .then((r) => setResponseTime(r))
      .catch((err) => console.error('[dashboard] response time failed:', err))
      .finally(() => setResponseTimeLoading(false));

    void loadActivity(db, 50)
      .then((a) => setActivity(a))
      .catch((err) => console.error('[dashboard] activity failed:', err))
      .finally(() => setActivityLoading(false));

    void db
      .from('contacts')
      .select(
        '*, lead_details(*), deals(status, pipeline_stages!deals_stage_id_fkey(name)), contact_tags(tags(name))'
      )
      .order('created_at', { ascending: false })
      .order('created_at', { referencedTable: 'deals', ascending: false })
      .limit(5)
      .then(({ data, error }) => {
        if (error) console.error('[dashboard] recent leads failed:', error);
        else setRecentLeads(data || []);
        setRecentLeadsLoading(false);
      });

    const todayStart = new Date();
    todayStart.setHours(0, 0, 0, 0);
    const todayEnd = new Date();
    todayEnd.setHours(23, 59, 59, 999);

    void db
      .from('site_visits')
      .select('*, contacts(name), properties(title)')
      .gte('scheduled_at', todayStart.toISOString())
      .lte('scheduled_at', todayEnd.toISOString())
      .order('scheduled_at', { ascending: true })
      .then(({ data, error }) => {
        if (error) console.error('[dashboard] today visits failed:', error);
        else setTodayVisits(data || []);
        setTodayVisitsLoading(false);
      });
  }, []);

  useEffect(() => {
    loadAll();
  }, [loadAll]);

  const handleRangeChange = useCallback(
