'use client';

import { useEffect, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { Loader2 } from 'lucide-react';
import { toast } from 'sonner';

import { useTranslations } from 'next-intl';

import { FlowEditorShell } from '@/components/flows/flow-editor-shell';
import type { FlowRow, FlowNodeRow } from '@/lib/flows/types';

/**
 * Flow editor shell.
 *
 * Loads `{flow, nodes}` from `/api/flows/[id]` and hands it to
 * `<FlowBuilder>`. Owns the loading/error state so the builder can
 * focus purely on editing.
 *
 * Open to every authenticated user — the beta gate that previously
 * 404'd non-beta accounts was removed in PR #134. The API still
 * 404s on a flow id the caller doesn't own (RLS), which becomes the
 * "Flow not found" state below.
 */
export default function FlowEditorPage() {
  const router = useRouter();
  const params = useParams<{ id: string }>();
  const t = useTranslations('Flows.edit');

  const [flow, setFlow] = useState<FlowRow | null>(null);
  const [nodes, setNodes] = useState<FlowNodeRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [notFound, setNotFound] = useState(false);

  useEffect(() => {
    if (window.innerWidth < 768) {
      router.push('/flows');
    }
  }, [router]);

  useEffect(() => {
    if (!params.id) return;
    let cancelled = false;
    (async () => {
      try {
        const res = await fetch(`/api/flows/${params.id}`);
        if (res.status === 404) {
          if (!cancelled) setNotFound(true);
          return;
        }
        if (!res.ok) throw new Error(`Failed: ${res.status}`);
        const json = (await res.json()) as {
          flow: FlowRow;
          nodes: FlowNodeRow[];
        };
        if (!cancelled) {
          setFlow(json.flow);
          setNodes(json.nodes ?? []);
        }
      } catch (err) {
        if (!cancelled) {
          console.error(err);
          toast.error(t('loadError'));
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [params.id]);

  if (loading) {
    return (
      <div className="flex h-full items-center justify-center">
        <Loader2 className="text-muted-foreground h-6 w-6 animate-spin" />
      </div>
    );
  }
  if (notFound || !flow) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-3">
        <p className="text-muted-foreground text-sm">{t('notFound')}</p>
        <button
          type="button"
          onClick={() => router.push('/flows')}
          className="text-primary text-sm hover:opacity-80"
        >
          {t('backToFlows')}
        </button>
      </div>
    );
  }

  return <FlowEditorShell initialFlow={flow} initialNodes={nodes} />;
}

'use client';

import { useEffect, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import {
  ArrowLeft,
  Loader2,
  CircleCheck,
  CircleAlert,
  Clock,
  UserPlus,
  PlayCircle,
  PauseCircle,
  ChevronDown,
  ChevronRight,
} from 'lucide-react';
import { toast } from 'sonner';
import { format, formatDistanceToNow } from 'date-fns';

import { useTranslations } from 'next-intl';

import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';

/**
 * Run history viewer.
 *
 * Lists the 50 most recent runs for a flow, newest first. Each row
 * collapses to a one-liner (contact + status + time); expanding shows
 * the full `flow_run_events` timeline for that run — useful for
 * debugging "why didn't my flow advance?" by surfacing the engine's
 * own log.
 */

interface RunRow {
  id: string;
  status:
    | 'active'
    | 'completed'
    | 'handed_off'
    | 'timed_out'
    | 'paused_by_agent'
    | 'failed';
  current_node_key: string | null;
  started_at: string;
  last_advanced_at: string;
  ended_at: string | null;
  end_reason: string | null;
  vars: Record<string, unknown>;
  reprompt_count: number;
  contact: { id: string; name: string | null; phone: string } | null;
}

interface EventRow {
  flow_run_id: string;
  event_type: string;
  node_key: string | null;
  payload: Record<string, unknown>;
  created_at: string;
}

const STATUS_META: Record<
  RunRow['status'],
  { classes: string; icon: typeof Clock }
> = {
  active: {
    classes: 'border-emerald-600/40 bg-emerald-500/10 text-emerald-300',
    icon: PlayCircle,
  },
  completed: {
    classes: 'border-border bg-muted text-muted-foreground',
    icon: CircleCheck,
  },
  handed_off: {
    classes: 'border-amber-600/40 bg-amber-500/10 text-amber-300',
    icon: UserPlus,
  },
  timed_out: {
    classes: 'border-border bg-muted/60 text-muted-foreground',
    icon: Clock,
  },
  paused_by_agent: {
    classes: 'border-border bg-muted text-muted-foreground',
    icon: PauseCircle,
  },
  failed: {
    classes: 'border-red-600/40 bg-red-500/10 text-red-300',
    icon: CircleAlert,
  },
};

export default function FlowRunsPage() {
  const router = useRouter();
  const params = useParams<{ id: string }>();
  const t = useTranslations('Flows.logs');
  const tEdit = useTranslations('Flows.edit');

  const [flow, setFlow] = useState<{ id: string; name: string } | null>(null);
  const [runs, setRuns] = useState<RunRow[]>([]);
  const [events, setEvents] = useState<EventRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState<Set<string>>(new Set());
  const [notFound, setNotFound] = useState(false);

  useEffect(() => {
    if (!params.id) return;
    let cancelled = false;
    (async () => {
      try {
        const res = await fetch(`/api/flows/${params.id}/runs`);
        if (res.status === 404) {
          if (!cancelled) setNotFound(true);
          return;
        }
        if (!res.ok) throw new Error(`Failed: ${res.status}`);
        const json = (await res.json()) as {
          flow: { id: string; name: string };
          runs: RunRow[];
          events: EventRow[];
        };
        if (!cancelled) {
          setFlow(json.flow);
          setRuns(json.runs ?? []);
          setEvents(json.events ?? []);
        }
      } catch (err) {
        if (!cancelled) {
          console.error(err);
          toast.error(t('loadError'));
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [params.id]);

  function toggle(runId: string) {
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(runId)) next.delete(runId);
      else next.add(runId);
      return next;
    });
  }

  if (loading) {
    return (
      <div className="flex h-full items-center justify-center">
        <Loader2 className="text-muted-foreground h-6 w-6 animate-spin" />
      </div>
    );
  }
  if (notFound || !flow) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-3">
        <p className="text-muted-foreground text-sm">{tEdit('notFound')}</p>
        <button
          type="button"
          onClick={() => router.push('/flows')}
          className="text-primary text-sm hover:opacity-80"
        >
          {tEdit('backToFlows')}
        </button>
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-4xl p-6">
      <button
        type="button"
        onClick={() => router.push(`/flows/${flow.id}`)}
        className="text-muted-foreground hover:text-foreground mb-2 inline-flex items-center gap-1 text-xs"
      >
        <ArrowLeft className="h-3 w-3" />
        {flow.name}
      </button>
      <h1 className="text-foreground text-xl font-semibold">{t('title')}</h1>
      <p className="text-muted-foreground mt-1 text-sm">{t('description')}</p>

      {runs.length === 0 ? (
        <div className="border-border bg-card/50 text-muted-foreground mt-6 rounded-lg border border-dashed px-6 py-12 text-center text-sm">
          {t('emptyState')}
        </div>
      ) : (
        <div className="mt-6 flex flex-col gap-2">
          {runs.map((run) => (
            <RunCard
              key={run.id}
              run={run}
              events={events.filter((e) => e.flow_run_id === run.id)}
              expanded={expanded.has(run.id)}
              onToggle={() => toggle(run.id)}
              t={t}
            />
          ))}
        </div>
      )}
    </div>
  );
}

function RunCard({
  run,
  events,
  expanded,
  onToggle,
  t,
}: {
  run: RunRow;
  events: EventRow[];
  expanded: boolean;
  onToggle: () => void;
  t: ReturnType<typeof useTranslations>;
}) {
  const meta = STATUS_META[run.status];
  const StatusIcon = meta.icon;
  const contactLabel =
    run.contact?.name?.trim() || run.contact?.phone || t('unknownContact');
  const duration = run.ended_at
    ? formatDistanceToNow(new Date(run.ended_at), {
        addSuffix: false,
      })
    : null;
  return (
    <div className="border-border bg-card rounded-lg border">
      <button
        type="button"
        onClick={onToggle}
        className="flex w-full items-center gap-3 px-4 py-3 text-left"
      >
        {expanded ? (
          <ChevronDown className="text-muted-foreground h-4 w-4 shrink-0" />
        ) : (
          <ChevronRight className="text-muted-foreground h-4 w-4 shrink-0" />
        )}
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center gap-2">
            <span className="text-foreground truncate text-sm font-medium">
              {contactLabel}
            </span>
            <Badge variant="outline" className={cn('gap-1', meta.classes)}>
              <StatusIcon className="h-3 w-3" />
              {t(
                run.status === 'active'
                  ? 'statusActive'
                  : run.status === 'completed'
                    ? 'statusCompleted'
                    : run.status === 'handed_off'
                      ? 'statusHandedOff'
                      : run.status === 'timed_out'
                        ? 'statusTimedOut'
                        : run.status === 'paused_by_agent'
                          ? 'statusPaused'
                          : 'statusFailed'
              )}
            </Badge>
            {run.status === 'active' && run.current_node_key && (
              <code className="bg-muted text-muted-foreground rounded px-1.5 py-0.5 text-[10px]">
                {t('atNode', { node: run.current_node_key })}
              </code>
            )}
          </div>
          <div className="text-muted-foreground mt-0.5 flex flex-wrap items-center gap-2 text-[11px]">
            <span>
              {t('started', { time: format(new Date(run.started_at), 'PP p') })}
            </span>
            {run.reprompt_count > 0 && (
              <span>· {t('reprompts', { count: run.reprompt_count })}</span>
            )}
            {duration && <span>· {t('ranFor', { duration })}</span>}
          </div>
        </div>
      </button>
      {expanded && (
        <div className="border-border border-t px-4 py-3">
          {Object.keys(run.vars).length > 0 && (
            <details className="mb-3">
              <summary className="text-muted-foreground cursor-pointer text-xs">
                {t('capturedVars', { count: Object.keys(run.vars).length })}
              </summary>
              <pre className="bg-background text-muted-foreground mt-2 overflow-x-auto rounded-md p-2 text-[11px]">
                {JSON.stringify(run.vars, null, 2)}
              </pre>
            </details>
          )}
          <div className="flex flex-col gap-1">
            {events.length === 0 ? (
              <p className="text-muted-foreground text-xs">{t('noEvents')}</p>
            ) : (
              events.map((ev, ix) => <EventLine key={ix} ev={ev} />)
            )}
          </div>
        </div>
      )}
    </div>
  );
}

const EVENT_COLOR: Record<string, string> = {
  started: 'text-emerald-300',
  node_entered: 'text-muted-foreground',
  message_sent: 'text-sky-300',
  reply_received: 'text-primary',
  fallback_fired: 'text-amber-300',
  handoff: 'text-amber-300',
  timeout: 'text-muted-foreground',
  error: 'text-red-300',
  completed: 'text-emerald-300',
};

function EventLine({ ev }: { ev: EventRow }) {
  const cls = EVENT_COLOR[ev.event_type] ?? 'text-muted-foreground';
  return (
    <div className="flex items-start gap-2 rounded-md px-2 py-1 text-xs">
      <span className="text-muted-foreground w-32 shrink-0 text-[10px]">
        {format(new Date(ev.created_at), 'HH:mm:ss')}
      </span>
      <span className={cn('w-32 shrink-0 font-mono text-[10px]', cls)}>
        {ev.event_type}
      </span>
      {ev.node_key && (
        <code className="bg-muted text-muted-foreground shrink-0 rounded px-1 py-0.5 text-[10px]">
          {ev.node_key}
        </code>
      )}
      {Object.keys(ev.payload).length > 0 && (
        <span className="text-muted-foreground min-w-0 truncate text-[10px]">
          {summarizePayload(ev.payload)}
        </span>
      )}
    </div>
  );
}

function summarizePayload(payload: Record<string, unknown>): string {
  // Show the keys that matter most to a human debugger; full JSON is
  // available via the "Captured vars" details panel for the run.
  const keys = ['reply_id', 'captured_key', 'reason', 'advancing_to'];
  for (const k of keys) {
    if (k in payload && payload[k] !== null && payload[k] !== undefined) {
      return `${k}=${String(payload[k]).slice(0, 80)}`;
    }
  }
  return '';
}

