source:
'use client';

import { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { createClient } from '@/lib/supabase/client';
import type { Pipeline, PipelineStage, Deal } from '@/types';
import { PipelineBoard } from '@/components/pipelines/pipeline-board';
import { PipelineSettings } from '@/components/pipelines/pipeline-settings';
import { DealForm } from '@/components/pipelines/deal-form';
import { PipelineAnalytics } from '@/components/pipelines/pipeline-analytics';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  GitBranch,
  Plus,
  ChevronDown,
  Settings,
  Download,
  Trophy,
  XCircle,
  Kanban,
} from 'lucide-react';
import { toast } from 'sonner';
import { useCan } from '@/hooks/use-can';
import { useAuth } from '@/hooks/use-auth';
import { GatedButton } from '@/components/ui/gated-button';
import { useTranslations } from 'next-intl';
import { formatCurrency, formatINR } from '@/lib/currency';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { avatarColorForName, initialsForName } from '@/lib/avatar-color';

// Pipeline creation is admin-class (settings-tier write under
// the new RLS); deal creation is operational and only requires
// agent+. The two CTAs gate on different `useCan` capabilities,
// not on different copy.

// Spec-defined seed — name and color per the product spec.
// NOTE: Final stage is 'Booking / Token Paid', not 'Won' or 'Closed'.
// Won/Lost are outcomes expressed via deal.status, not stage names.
const SPEC_DEFAULT_STAGES = [
  { name: 'New Lead', color: '#3b82f6', position: 0 }, // blue
  { name: 'Qualified', color: '#eab308', position: 1 }, // yellow
  { name: 'Proposal Sent', color: '#f97316', position: 2 }, // orange
  { name: 'Negotiation', color: '#8b5cf6', position: 3 }, // purple
  { name: 'Booking / Token Paid', color: '#22c55e', position: 4 }, // green
];

// Filter tabs: what deals the board / list shows
type StatusFilter = 'open' | 'won' | 'lost' | 'all';

// A compact row in the Won/Lost list view
function ClosedDealRow({
  deal,
  defaultCurrency,
  onEdit,
}: {
  deal: Deal;
  defaultCurrency: string;
  onEdit: (deal: Deal) => void;
}) {
  const contactLabel =
    deal.contact?.name || deal.contact?.phone || 'No contact';
  const assigneeLabel = deal.assignee?.full_name;
  const closedDate = deal.closed_at
    ? new Date(deal.closed_at).toLocaleDateString('en-IN', {
        day: 'numeric',
        month: 'short',
        year: 'numeric',
      })
    : '—';

  return (
    <button
      type="button"
      onClick={() => onEdit(deal)}
      className="border-border/50 bg-card hover:bg-muted flex w-full items-center gap-3 rounded-xl border p-3 text-left transition-colors"
    >
      <span
        className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-xs font-bold ${
          deal.status === 'won'
            ? 'bg-primary/15 text-primary'
            : 'bg-red-500/15 text-red-400'
        }`}
      >
        {deal.status === 'won' ? '✓' : '✗'}
      </span>

      <div className="min-w-0 flex-1">
        <p className="text-foreground truncate text-sm font-semibold">
          {deal.title}
        </p>
        <div className="text-muted-foreground flex items-center gap-2 text-xs">
          <span className="truncate">{contactLabel}</span>
          {deal.status === 'lost' && deal.lost_reason && (
            <>
              <span>·</span>
              <span className="truncate text-red-400">
                {deal.lost_reason.label}
              </span>
            </>
          )}
        </div>
      </div>

      <div className="flex flex-col items-end gap-0.5">
        <span className="text-primary text-sm font-bold">
          {defaultCurrency === 'INR'
            ? formatINR(deal.value)
            : formatCurrency(deal.value, defaultCurrency)}
        </span>
        <span className="text-muted-foreground text-[11px]">{closedDate}</span>
      </div>

      {assigneeLabel && (
        <Avatar className="h-6 w-6 shrink-0">
          <AvatarFallback
            className="text-[10px] font-bold text-white"
            style={{ background: avatarColorForName(assigneeLabel) }}
          >
            {initialsForName(assigneeLabel)}
          </AvatarFallback>
        </Avatar>
      )}
    </button>
  );
}

export default function PipelinesPage() {
  const t = useTranslations('Pipelines.page');
  const supabase = createClient();
  const canEditSettings = useCan('edit-settings');
  const canCreateDeals = useCan('send-messages');
  const { accountId, accountRole, defaultCurrency } = useAuth();

  const [pipelines, setPipelines] = useState<Pipeline[]>([]);
  const [selectedPipelineId, setSelectedPipelineId] = useState<string>('');
  const [stages, setStages] = useState<PipelineStage[]>([]);
  const [deals, setDeals] = useState<Deal[]>([]);
  const [loading, setLoading] = useState(true);

  // Status filter — drives what the board / list shows
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('open');

  // Dialog / sheet state
  const [newPipelineOpen, setNewPipelineOpen] = useState(false);
  const [newPipelineName, setNewPipelineName] = useState('');
  const [creating, setCreating] = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);

  // Deal form state is lifted here so both the top-bar "Add Deal" and
  // the per-column "+" trigger the same Sheet.
  const [dealFormOpen, setDealFormOpen] = useState(false);
  const [editingDeal, setEditingDeal] = useState<Deal | null>(null);
  const [defaultStageId, setDefaultStageId] = useState<string>('');

  // Guard against double-seeding (React StrictMode double-effect in dev).
  const seedAttempted = useRef(false);

  const loadPipelines = useCallback(async () => {
    const { data, error } = await supabase
      .from('pipelines')
      .select('*')
      .order('created_at');
    if (error) {
      console.error('Failed to load pipelines:', error.message);
      return [];
    }
    return data ?? [];
  }, [supabase]);

  const loadStages = useCallback(
    async (pipelineId: string) => {
      const { data } = await supabase
        .from('pipeline_stages')
        .select('*')
        .eq('pipeline_id', pipelineId)
        .order('position');
      return data ?? [];
    },
    [supabase]
  );

  const loadDeals = useCallback(
    async (pipelineId: string) => {
      // Load ALL deals (all statuses) so the client-side filter can switch
      // between Open / Won / Lost / All without a new network round-trip.
      // Closed deals are a small fraction of the total so fetching all is safe.
      const { data } = await supabase
        .from('deals')
        .select(
          '*, contact:contacts(*, lead_details(*)), assignee:profiles!deals_assigned_to_fkey(*), lost_reason:lost_reasons(*)'
        )
        .eq('pipeline_id', pipelineId)
        .order('created_at', { ascending: false });
      return (data ?? []) as Deal[];
    },
    [supabase]
  );

  const seedDefaultPipeline =
    useCallback(async (): Promise<Pipeline | null> => {
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const user = session?.user;
      if (!user) return null;
      // pipelines.account_id is NOT NULL post-017 with no DB default.
      if (!accountId) return null;

      const { data: pipeline, error } = await supabase
        .from('pipelines')
        .insert({
          user_id: user.id,
          account_id: accountId,
          name: 'Sales Pipeline',
        })
        .select()
        .single();

      if (error || !pipeline) {
        console.error('Failed to seed pipeline:', error?.message);
        return null;
      }

      const stagesPayload = SPEC_DEFAULT_STAGES.map((s) => ({
        pipeline_id: pipeline.id,
        name: s.name,
        color: s.color,
        position: s.position,
      }));
      await supabase.from('pipeline_stages').insert(stagesPayload);

      return pipeline as Pipeline;
    }, [supabase, accountId]);

  // Initial load + seed-if-empty.
  // Seeding is gated to admin+ only: an agent who just accepted an
  // invitation joins an existing account that already has a "Real
  // Estate" pipeline (seeded by the handle_new_user trigger for the
  // owner). If the pipeline list appears empty for a moment during
  // the initial fetch, we must NOT let an agent create a duplicate
  // "Sales Pipeline" on top of it. The seed is purely a fallback for
  // net-new owner accounts that somehow have no pipeline at all.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      setLoading(true);
      let list = await loadPipelines();

      // Only seed if the user can edit account settings (admin+) AND
      // there are truly no pipelines, AND we haven't tried once already.
      const canSeed = accountRole === 'owner' || accountRole === 'admin';
      if (list.length === 0 && canSeed && !seedAttempted.current) {
        seedAttempted.current = true;
        const seeded = await seedDefaultPipeline();
        if (seeded) list = await loadPipelines();
      }

      if (cancelled) return;
      setPipelines(list);
      if (list.length > 0) {
        setSelectedPipelineId((prev) =>
          prev && list.some((p) => p.id === prev) ? prev : list[0].id
        );
      } else {
        setSelectedPipelineId('');
      }
      setLoading(false);
    })();
    return () => {
      cancelled = true;
    };
  }, [loadPipelines, seedDefaultPipeline, accountRole]);

  // Load stages + deals whenever selected pipeline changes.
  // Clearing on no-selection is a legitimate sync with URL/prop
  // state; the load completion uses async setters inside promise
  // callbacks (not synchronous in the effect body).
  useEffect(() => {
    if (!selectedPipelineId) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setStages([]);
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setDeals([]);
      return;
    }
    let cancelled = false;
    (async () => {
      const [s, d] = await Promise.all([
        loadStages(selectedPipelineId),
        loadDeals(selectedPipelineId),
      ]);
      if (cancelled) return;
      setStages(s);
      setDeals(d);
    })();
    return () => {
      cancelled = true;
    };
  }, [selectedPipelineId, loadStages, loadDeals]);

  const refreshPipelines = useCallback(async () => {
    const list = await loadPipelines();
    setPipelines(list);
    if (list.length === 0) setSelectedPipelineId('');
    else if (!list.some((p) => p.id === selectedPipelineId))
      setSelectedPipelineId(list[0].id);
  }, [loadPipelines, selectedPipelineId]);

  const refreshStages = useCallback(async () => {
    if (!selectedPipelineId) return;
    setStages(await loadStages(selectedPipelineId));
  }, [loadStages, selectedPipelineId]);

  const refreshDeals = useCallback(async () => {
    if (!selectedPipelineId) return;
    setDeals(await loadDeals(selectedPipelineId));
  }, [loadDeals, selectedPipelineId]);

  const handleDealMoved = useCallback(
    async (dealId: string, newStageId: string) => {
      // Optimistic update — board already animated; just persist.
      setDeals((prev) =>
        prev.map((d) => (d.id === dealId ? { ...d, stage_id: newStageId } : d))
      );
      const res = await fetch(`/api/deals/${dealId}`, {
        method: 'PATCH',
        body: JSON.stringify({ stage_id: newStageId }),
        headers: { 'Content-Type': 'application/json' },
      });
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        if (body.error === 'DEAL_NOT_YOURS') {
          setDeals((prev) => {
            const deal = prev.find((d) => d.id === dealId);
            const ownerName =
              deal?.assignee?.full_name ||
              deal?.assignee?.email ||
              'another agent';
            toast.error(
              `This lead belongs to ${ownerName}. Contact your admin to move it.`
            );
            return prev;
          });
        } else {
          toast.error(t('toastFailedMoveDeal'));
        }
        refreshDeals();
      }
    },
    [refreshDeals, t]
  );

  const handleAddDeal = useCallback(
    (stageId?: string) => {
      setEditingDeal(null);
      setDefaultStageId(stageId ?? stages[0]?.id ?? '');
      setDealFormOpen(true);
    },
    [stages]
  );

  const handleEditDeal = useCallback((deal: Deal) => {
    setEditingDeal(deal);
    setDefaultStageId(deal.stage_id);
    setDealFormOpen(true);
  }, []);

  async function handleCreatePipeline() {
    const name = newPipelineName.trim();
    if (!name) return;
    setCreating(true);

    const {
      data: { session },
    } = await supabase.auth.getSession();
    const user = session?.user;
    if (!user) {
      setCreating(false);
      return;
    }
    // pipelines.account_id is NOT NULL post-017 with no DB default.
    if (!accountId) {
      toast.error(t('toastNotLinkedToAccount'));
      setCreating(false);
      return;
    }

    const { data: pipeline, error } = await supabase
      .from('pipelines')
      .insert({ user_id: user.id, account_id: accountId, name })
      .select()
      .single();

    if (error || !pipeline) {
      toast.error(t('toastFailedCreatePipeline'));
      setCreating(false);
      return;
    }

    const stagesPayload = SPEC_DEFAULT_STAGES.map((s) => ({
      pipeline_id: pipeline.id,
      name: s.name,
      color: s.color,
      position: s.position,
    }));
    await supabase.from('pipeline_stages').insert(stagesPayload);

    setNewPipelineName('');
    setNewPipelineOpen(false);
    setSelectedPipelineId(pipeline.id);
    await refreshPipelines();
    setCreating(false);
    toast.success(t('toastPipelineCreated'));
  }

  const selectedPipeline = pipelines.find((p) => p.id === selectedPipelineId);

  // Deals shown on the board are always only open ones.
  // Won / Lost views use the list view below.
  const openDeals = useMemo(
    () => deals.filter((d) => d.status === 'open' || !d.status),
    [deals]
  );
  const wonDeals = useMemo(
    () => deals.filter((d) => d.status === 'won'),
    [deals]
  );
  const lostDeals = useMemo(
    () => deals.filter((d) => d.status === 'lost'),
    [deals]
  );

  // Counts for filter tabs
  const filterCounts: Record<StatusFilter, number> = {
    open: openDeals.length,
    won: wonDeals.length,
    lost: lostDeals.length,
    all: deals.length,
  };

  // Deals shown in the closed list view
  const closedListDeals = useMemo(() => {
    if (statusFilter === 'won') return wonDeals;
    if (statusFilter === 'lost') return lostDeals;
    if (statusFilter === 'all') return deals;
    return [];
  }, [statusFilter, wonDeals, lostDeals, deals]);

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div className="bg-muted h-8 w-48 animate-pulse rounded" />
          <div className="bg-muted h-9 w-28 animate-pulse rounded-lg" />
        </div>
        <div className="flex gap-3">
          {[1, 2, 3, 4, 5].map((i) => (
            <div
              key={i}
              className="bg-muted/50 h-96 w-72 animate-pulse rounded-xl"
            />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          {/* Pipeline selector dropdown */}
          <DropdownMenu>
            <DropdownMenuTrigger className="border-border bg-card text-foreground hover:bg-muted data-[popup-open]:bg-muted inline-flex items-center gap-2 rounded-lg border px-3 py-2 text-sm transition-colors">
              <GitBranch className="text-primary h-4 w-4" />
              <span className="font-semibold">
                {selectedPipeline?.name ?? t('selectPipeline')}
              </span>
              <ChevronDown className="text-muted-foreground h-4 w-4" />
            </DropdownMenuTrigger>
            <DropdownMenuContent
              align="start"
              className="border-border bg-popover text-popover-foreground w-64"
            >
              {pipelines.length === 0 && (
                <DropdownMenuItem disabled className="text-muted-foreground">
                  {t('noPipelinesYet')}
                </DropdownMenuItem>
              )}
              {pipelines.map((p) => (
                <DropdownMenuItem
                  key={p.id}
                  onClick={() => setSelectedPipelineId(p.id)}
                  className={
                    p.id === selectedPipelineId
                      ? 'text-primary'
                      : 'text-popover-foreground'
                  }
                >
                  <GitBranch className="mr-2 h-3.5 w-3.5" />
                  {p.name}
                </DropdownMenuItem>
              ))}
              <DropdownMenuSeparator className="bg-border" />
              {selectedPipeline && (
                <DropdownMenuItem
                  onClick={() => setSettingsOpen(true)}
                  className="text-popover-foreground"
                >
                  <Settings className="mr-2 h-3.5 w-3.5" />
                  {t('managePipelines')}
                </DropdownMenuItem>
              )}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>

        <div className="flex items-center gap-2">
          <GatedButton
            variant="outline"
            canAct={canEditSettings}
            gateReason="export deals"
            onClick={() => {
              window.location.href = '/api/deals/export';
            }}
            className="border-border bg-card text-foreground hover:bg-muted"
          >
            <Download className="mr-1 h-4 w-4" />
            Export
          </GatedButton>
          <GatedButton
            variant="outline"
            canAct={canEditSettings}
            gateReason="create pipelines"
            onClick={() => setNewPipelineOpen(true)}
            className="border-border bg-card text-foreground hover:bg-muted"
          >
            <Plus className="mr-1 h-4 w-4" />
            {t('addPipeline')}
          </GatedButton>
          {statusFilter === 'open' && (
            <GatedButton
              canAct={canCreateDeals}
              gateReason="create deals"
              disabled={!selectedPipelineId || stages.length === 0}
              onClick={() => handleAddDeal()}
              className="bg-primary text-primary-foreground hover:bg-primary/90"
            >
              <Plus className="mr-1 h-4 w-4" />
              {t('addDeal')}
            </GatedButton>
          )}
        </div>
      </div>

      {/* Status filter tabs */}
      {pipelines.length > 0 && (
        <div
          className="border-border flex gap-1 rounded-xl border p-1"
          style={{ width: 'fit-content' }}
        >
          {(
            [
              {
                key: 'open' as StatusFilter,
                label: t('filterOpen'),
                icon: <Kanban className="h-3.5 w-3.5" />,
              },
              {
                key: 'won' as StatusFilter,
                label: t('filterWon'),
                icon: <Trophy className="h-3.5 w-3.5" />,
              },
              {
                key: 'lost' as StatusFilter,
                label: t('filterLost'),
                icon: <XCircle className="h-3.5 w-3.5" />,
              },
              { key: 'all' as StatusFilter, label: t('filterAll'), icon: null },
            ] as { key: StatusFilter; label: string; icon: React.ReactNode }[]
          ).map(({ key, label, icon }) => (
            <button
              key={key}
              type="button"
              onClick={() => setStatusFilter(key)}
              className={`flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
                statusFilter === key
                  ? 'bg-primary text-primary-foreground'
                  : 'text-muted-foreground hover:bg-muted hover:text-foreground'
              }`}
            >
              {icon}
              {label}
              <span
                className={`rounded-full px-1.5 py-0.5 text-[10px] font-semibold ${
                  statusFilter === key
                    ? 'bg-primary-foreground/20 text-primary-foreground'
                    : 'bg-muted text-muted-foreground'
                }`}
              >
                {filterCounts[key]}
              </span>
            </button>
          ))}
        </div>
      )}

      {/* Board or list based on selected filter */}
      {pipelines.length === 0 ? (
        <div className="border-border flex flex-col items-center justify-center rounded-xl border border-dashed py-20">
          <GitBranch className="text-muted-foreground h-12 w-12" />
          <h3 className="text-foreground mt-4 text-lg font-medium">
            {t('noPipelinesYet')}
          </h3>
          <p className="text-muted-foreground mt-2 text-sm">
            {t('createToStartTracking')}
          </p>
          <GatedButton
            canAct={canEditSettings}
            gateReason="create pipelines"
            onClick={() => setNewPipelineOpen(true)}
            className="bg-primary text-primary-foreground hover:bg-primary/90 mt-4"
          >
            <Plus className="mr-1 h-4 w-4" />
            {t('createPipeline')}
          </GatedButton>
        </div>
      ) : statusFilter === 'open' ? (
        <>
          <PipelineAnalytics stages={stages} deals={deals} />
          <PipelineBoard
            stages={stages}
            deals={openDeals}
            onDealMoved={handleDealMoved}
            onAddDeal={handleAddDeal}
            onEditDeal={handleEditDeal}
          />
        </>
      ) : (
        <>
          <PipelineAnalytics stages={stages} deals={deals} />
          {/* Won / Lost / All list view */}
          <div className="space-y-2">
            {closedListDeals.length === 0 ? (
              <div className="border-border text-muted-foreground flex flex-col items-center justify-center rounded-xl border border-dashed py-16 text-sm">
                {statusFilter === 'won' && (
                  <>
                    <Trophy className="mb-2 h-8 w-8 opacity-40" />
                    <p>{t('noWonDeals')}</p>
                  </>
                )}
                {statusFilter === 'lost' && (
                  <>
                    <XCircle className="mb-2 h-8 w-8 opacity-40" />
                    <p>{t('noLostDeals')}</p>
                  </>
                )}
                {statusFilter === 'all' && <p>{t('noDeals')}</p>}
              </div>
            ) : (
              closedListDeals.map((deal) => (
                <ClosedDealRow
                  key={deal.id}
                  deal={deal}
                  defaultCurrency={defaultCurrency}
                  onEdit={handleEditDeal}
                />
              ))
            )}
          </div>
        </>
      )}

      {/* New Pipeline Dialog */}
      <Dialog open={newPipelineOpen} onOpenChange={setNewPipelineOpen}>
        <DialogContent className="bg-popover border-border sm:max-w-sm">
          <DialogHeader>
            <DialogTitle className="text-popover-foreground">
              {t('newPipeline')}
            </DialogTitle>
          </DialogHeader>
          <div className="py-2">
            <Label className="text-muted-foreground">{t('pipelineName')}</Label>
            <Input
              value={newPipelineName}
              onChange={(e) => setNewPipelineName(e.target.value)}
              placeholder={t('pipelineNamePlaceholder')}
              className="bg-muted border-border text-foreground mt-2"
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleCreatePipeline();
              }}
            />
            <p className="text-muted-foreground mt-2 text-xs">
              {t('defaultStagesDesc')}
            </p>
          </div>
          <DialogFooter className="bg-popover/50 border-border">
            <Button
              variant="outline"
              onClick={() => setNewPipelineOpen(false)}
              className="border-border text-muted-foreground hover:bg-muted"
            >
              {t('cancel')}
            </Button>
            <Button
              onClick={handleCreatePipeline}
              disabled={creating || !newPipelineName.trim()}
              className="bg-primary text-primary-foreground hover:bg-primary/90"
            >
              {creating ? t('creating') : t('createPipelineBtn')}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Pipeline Settings */}
      {selectedPipeline && (
        <PipelineSettings
          open={settingsOpen}
          onOpenChange={setSettingsOpen}
          pipeline={selectedPipeline}
          stages={stages}
          onPipelinesChanged={refreshPipelines}
          onStagesChanged={refreshStages}
          onCreateNewPipeline={() => {
            setSettingsOpen(false);
            setNewPipelineOpen(true);
          }}
        />
      )}

      {/* Deal Form (Sheet) */}
      <DealForm
        open={dealFormOpen}
        onOpenChange={setDealFormOpen}
        deal={editingDeal}
        pipelineId={selectedPipelineId}
        stages={stages}
        defaultStageId={defaultStageId}
        onSaved={refreshDeals}
      />
    </div>
  );
}

