'use client';

import { useState, useEffect, useCallback } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { createClient } from '@/lib/supabase/client';
import type { Property } from '@/types';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import {
  MapPin,
  Building,
  IndianRupee,
  Bed,
  ChevronLeft,
  Loader2,
  AlertTriangle,
  CheckCircle2,
  Calendar,
  Maximize,
} from 'lucide-react';
import { useTranslations } from 'next-intl';
import { useAuth } from '@/hooks/use-auth';
import { formatCurrency, formatINR } from '@/lib/currency';
import Link from 'next/link';
import { EmiCalculator } from '@/components/properties/emi-calculator';

export default function PropertyDetailPage() {
  const t = useTranslations('Properties.detail');
  const params = useParams();
  const router = useRouter();
  const supabase = createClient();
  const { account } = useAuth();
  const defaultCurrency = account?.default_currency || 'INR';

  const [property, setProperty] = useState<Property | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchProperty = useCallback(async () => {
    if (!params.id) return;
    setLoading(true);

    const { data, error } = await supabase
      .from('properties')
      .select('*')
      .eq('id', params.id as string)
      .single();

    if (!error && data) {
      setProperty(data);
    }
    setLoading(false);
  }, [supabase, params.id]);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchProperty();
  }, [fetchProperty]);

  if (loading) {
    return (
      <div className="flex h-full flex-col items-center justify-center">
        <Loader2 className="text-primary size-8 animate-spin" />
      </div>
    );
  }

  if (!property) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <p className="text-muted-foreground">Property not found.</p>
        <Button variant="link" onClick={() => router.push('/properties')}>
          Back to Properties
        </Button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button
          variant="ghost"
          size="icon"
          onClick={() => router.push('/properties')}
          className="shrink-0"
        >
          <ChevronLeft className="size-5" />
        </Button>
        <div>
          <div className="flex items-center gap-3">
            <h1 className="text-foreground text-2xl font-bold">
              {property.title}
            </h1>
            {property.configuration && (
              <Badge
                variant="default"
                className="bg-primary text-primary-foreground px-3 py-1 text-sm font-bold"
              >
                {property.configuration}
              </Badge>
            )}
          </div>
          <div className="mt-2">
            {property.rera_id ? (
              <Badge
                variant="outline"
                className="border-green-500/30 bg-green-500/10 text-green-700"
              >
                <CheckCircle2 className="mr-1 size-3" />
                RERA: {property.rera_id}
              </Badge>
            ) : (
              <Badge
                variant="outline"
                className="border-amber-500/30 bg-amber-500/10 text-amber-700"
              >
                <AlertTriangle className="mr-1 size-3" />
                RERA ID missing — required under RERA Act 2016
              </Badge>
            )}
          </div>
        </div>
      </div>

      <Card>
        <CardContent className="p-6">
          <div className="grid gap-6 sm:grid-cols-2">
            {property.price && (
              <div className="flex items-center gap-3">
                <div className="bg-primary/10 text-primary flex size-10 shrink-0 items-center justify-center rounded-full">
                  <IndianRupee className="size-5" />
                </div>
                <div>
                  <p className="text-muted-foreground text-sm font-medium">
                    {t('price')}
                  </p>
                  <p className="text-lg font-semibold">
                    {defaultCurrency === 'INR'
                      ? formatINR(property.price)
                      : formatCurrency(property.price, defaultCurrency)}
                  </p>
                </div>
              </div>
            )}

            {property.location && (
              <div className="flex items-center gap-3">
                <div className="bg-primary/10 text-primary flex size-10 shrink-0 items-center justify-center rounded-full">
                  <MapPin className="size-5" />
                </div>
                <div>
                  <p className="text-muted-foreground text-sm font-medium">
                    Location
                  </p>
                  <p className="text-lg font-semibold">{property.location}</p>
                </div>
              </div>
            )}

            {property.property_type && (
              <div className="flex items-center gap-3">
                <div className="bg-primary/10 text-primary flex size-10 shrink-0 items-center justify-center rounded-full">
                  <Building className="size-5" />
                </div>
                <div>
                  <p className="text-muted-foreground text-sm font-medium">
                    {t('type')}
                  </p>
                  <p className="text-lg font-semibold">
                    {property.property_type}
                  </p>
                </div>
              </div>
            )}

            {property.bedrooms !== undefined && property.bedrooms !== null && (
              <div className="flex items-center gap-3">
                <div className="bg-primary/10 text-primary flex size-10 shrink-0 items-center justify-center rounded-full">
                  <Bed className="size-5" />
                </div>
                <div>
                  <p className="text-muted-foreground text-sm font-medium">
                    {t('bedrooms')}
                  </p>
                  <p className="text-lg font-semibold">{property.bedrooms}</p>
                </div>
              </div>
            )}

            {property.possession_status && (
              <div className="flex items-center gap-3">
                <div className="bg-primary/10 text-primary flex size-10 shrink-0 items-center justify-center rounded-full">
                  <Calendar className="size-5" />
                </div>
                <div>
                  <p className="text-muted-foreground text-sm font-medium">
                    Possession Status
                  </p>
                  <p className="text-lg font-semibold capitalize">
                    {property.possession_status.replace(/_/g, ' ')}
                  </p>
                </div>
              </div>
            )}

            {property.carpet_area && (
              <div className="flex items-center gap-3">
                <div className="bg-primary/10 text-primary flex size-10 shrink-0 items-center justify-center rounded-full">
                  <Maximize className="size-5" />
                </div>
                <div>
                  <p className="text-muted-foreground text-sm font-medium">
                    Carpet Area
                  </p>
                  <p className="text-lg font-semibold">
                    {property.carpet_area} sq ft
                  </p>
                </div>
              </div>
            )}
          </div>

          {property.tags && property.tags.length > 0 && (
            <div className="border-border mt-8 border-t pt-6">
              <p className="text-muted-foreground mb-3 text-sm font-medium">
                {t('tags')}
              </p>
              <div className="flex flex-wrap gap-2">
                {property.tags.map((tag, i) => (
                  <Badge key={i} variant="secondary">
                    {tag}
                  </Badge>
                ))}
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Section R7: EMI Calculator */}
      <div className="mt-6">
        <EmiCalculator propertyPrice={property.price ?? null} />
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import type { Property } from '@/types';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import {
  Search,
  MapPin,
  Building,
  IndianRupee,
  Loader2,
  Plus,
  Pencil,
  Trash2,
} from 'lucide-react';
import { useTranslations } from 'next-intl';
import Link from 'next/link';
import { PullToRefresh } from '@/components/layout/pull-to-refresh';

export default function PropertiesPage() {
  const t = useTranslations('Properties.page');
  const supabase = createClient();

  const [properties, setProperties] = useState<Property[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [typeFilter, setTypeFilter] = useState('');

  const fetchProperties = useCallback(async () => {
    setLoading(true);
    let query = supabase
      .from('properties')
      .select('*')
      .order('created_at', { ascending: false });

    if (search.trim()) {
      const term = `%${search.trim()}%`;
      query = query.or(`title.ilike.${term},location.ilike.${term}`);
    }

    if (typeFilter.trim()) {
      query = query.eq('property_type', typeFilter.trim());
    }

    const { data, error } = await query;
    if (error) {
      console.error(error);
    } else {
      setProperties(data ?? []);
    }
    setLoading(false);
  }, [supabase, search, typeFilter]);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchProperties();
  }, [fetchProperties]);

  return (
    <PullToRefresh onRefresh={fetchProperties}>
      <div className="space-y-6 pb-20">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h1 className="text-foreground text-2xl font-bold">{t('title')}</h1>
            <p className="text-muted-foreground mt-1 text-sm">
              {t('subtitle')}
            </p>
          </div>
          <div className="flex items-center gap-2">
            {/* Add property form not implemented here per plan but could be a dialog */}
          </div>
        </div>

        <div className="bg-background/95 sticky top-0 z-10 -mx-4 space-y-2 px-4 py-2 backdrop-blur sm:static sm:mx-0 sm:bg-transparent sm:px-0 sm:py-0">
          <div className="flex flex-col gap-2 sm:flex-row">
            <div className="relative w-full max-w-sm">
              <Search className="text-muted-foreground absolute top-1/2 left-2.5 size-4 -translate-y-1/2" />
              <Input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder={t('searchPlaceholder')}
                className="bg-card border-border text-foreground placeholder:text-muted-foreground pl-8"
              />
            </div>
            <Input
              value={typeFilter}
              onChange={(e) => setTypeFilter(e.target.value)}
              placeholder={t('filterType')}
              className="bg-card border-border text-foreground placeholder:text-muted-foreground w-full max-w-[200px]"
            />
          </div>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center gap-2 py-12">
            <Loader2 className="text-primary size-6 animate-spin" />
          </div>
        ) : properties.length === 0 ? (
          <div className="flex flex-col items-center gap-2 py-12">
            <Building className="text-muted-foreground size-8" />
            <p className="text-muted-foreground text-sm">{t('noProperties')}</p>
          </div>
        ) : (
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {properties.map((property) => (
              <Link key={property.id} href={`/properties/${property.id}`}>
                <Card className="hover:border-primary/50 h-full cursor-pointer transition-colors">
                  <CardHeader className="p-4 pb-2">
                    <div className="flex items-start justify-between">
                      <CardTitle className="line-clamp-1 text-base font-semibold">
                        {property.title}
                      </CardTitle>
                      {property.price && (
                        <Badge
                          variant="secondary"
                          className="flex shrink-0 items-center gap-1"
                        >
                          <IndianRupee className="size-3" />
                          {property.price.toLocaleString()}
                        </Badge>
                      )}
                    </div>
                  </CardHeader>
                  <CardContent className="p-4 pt-0">
                    <div className="text-muted-foreground flex flex-col gap-2 text-sm">
                      {property.location && (
                        <div className="flex items-center gap-1.5">
                          <MapPin className="size-3.5" />
                          <span className="truncate">{property.location}</span>
                        </div>
                      )}
                      {property.property_type && (
                        <div className="flex items-center gap-1.5">
                          <Building className="size-3.5" />
                          <span>{property.property_type}</span>
                          {property.bedrooms && (
                            <span className="border-border ml-1 border-l pl-2">
                              {property.bedrooms} Beds
                            </span>
                          )}
                        </div>
                      )}
                    </div>
                    {property.tags && property.tags.length > 0 && (
                      <div className="mt-3 flex flex-wrap gap-1.5">
                        {property.tags.slice(0, 3).map((tag, i) => (
                          <span
                            key={i}
                            className="bg-muted text-muted-foreground rounded px-1.5 py-0.5 text-[10px] font-medium"
                          >
                            {tag}
                          </span>
                        ))}
                        {property.tags.length > 3 && (
                          <span className="bg-muted text-muted-foreground rounded px-1.5 py-0.5 text-[10px] font-medium">
                            +{property.tags.length - 3}
                          </span>
                        )}
                      </div>
                    )}
                  </CardContent>
                </Card>
              </Link>
            ))}
          </div>
        )}
      </div>
    </PullToRefresh>
  );
}

'use client';

import { Suspense, useMemo, type ReactNode } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { useTranslations } from 'next-intl';

import { useAuth } from '@/hooks/use-auth';
import { useTheme } from '@/hooks/use-theme';
import { SettingsRail } from '@/components/settings/settings-rail';
import { SettingsOverview } from '@/components/settings/settings-overview';
import { ProfileForm } from '@/components/settings/profile-form';
import { SecurityPanel } from '@/components/settings/security-panel';
import { AppearancePanel } from '@/components/settings/appearance-panel';
import { WhatsAppConfig } from '@/components/settings/whatsapp-config';
import { TemplateManager } from '@/components/settings/template-manager';
import { QuickRepliesManager } from '@/components/settings/quick-replies-manager';
import { FieldsAndTagsPanel } from '@/components/settings/fields-and-tags-panel';
import { DealsSettings } from '@/components/settings/deals-settings';
import { MembersTab } from '@/components/settings/members-tab';
import { ApiKeysSettings } from '@/components/settings/api-keys-settings';
import { RoutingSettings } from '@/components/settings/routing-settings';
import { BillingTab } from '@/components/settings/billing-tab';
import { CostSheetConfig } from '@/components/settings/cost-sheet-config';
import {
  resolveSection,
  type SettingsSection,
} from '@/components/settings/settings-sections';

// `useSearchParams` opts this page out of static prerendering unless it
// sits under a Suspense boundary. Without one, the production build hits
// the "missing Suspense with CSR bailout" error and the whole page bails
// to client-side rendering — shipping a settings screen whose rail never
// wires up its click handlers. You land on the section the URL carried
// (the account-menu Settings link points at `?tab=whatsapp`) and can't
// navigate away. Mirror the login/signup split: a thin wrapper supplies
// the boundary; the inner component reads the query string.
export default function SettingsPage() {
  return (
    <Suspense fallback={null}>
      <SettingsPageInner />
    </Suspense>
  );
}

function SettingsPageInner() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { defaultCurrency, accountRole, isAgent, isViewer } = useAuth();
  const { mode } = useTheme();
  const t = useTranslations('Settings');

  // The URL (`?tab=`) is the single source of truth for the active
  // section — deep-linkable, and it keeps the existing links in the
  // app sidebar/header working. Legacy tab values (tags, custom-fields)
  // resolve onto their new home; unknown/empty → the Overview landing.
  const section = resolveSection(searchParams.get('tab'));

  const go = (next: SettingsSection) => {
    const params = new URLSearchParams(searchParams.toString());
    params.set('tab', next);
    router.replace(`/settings?${params.toString()}`, { scroll: false });
  };

  // Cheap, fetch-free rail hints. The Overview landing carries the
  // full live status/counts; the rail just surfaces the two that are
  // already in context.
  const hints: Partial<Record<SettingsSection, ReactNode>> = useMemo(
    () => ({
      appearance: mode.charAt(0).toUpperCase() + mode.slice(1),
      deals: defaultCurrency,
    }),
    [mode, defaultCurrency]
  );

  const panel: Record<SettingsSection, ReactNode> = {
    overview: <SettingsOverview onSelect={go} />,
    profile: <ProfileForm />,
    security: <SecurityPanel />,
    appearance: <AppearancePanel />,
    whatsapp: <WhatsAppConfig />,
    templates: <TemplateManager />,
    'quick-replies': <QuickRepliesManager />,
    fields: <FieldsAndTagsPanel />,
    deals: <DealsSettings />,
    members: <MembersTab />,
    api: <ApiKeysSettings />,
    routing: <RoutingSettings />,
    billing: <BillingTab />,
    'cost-sheet': <CostSheetConfig />,
  };

  const restrictedForAgent = !['profile', 'appearance', 'security'].includes(
    section
  );
  if ((isAgent || isViewer) && restrictedForAgent) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-center">
        <h2 className="mb-2 text-xl font-semibold">Access Restricted</h2>
        <p className="text-muted-foreground">
          Contact your admin to manage account settings.
        </p>
        <button
          onClick={() => go('profile')}
          className="text-primary mt-6 hover:underline"
        >
          Go to Profile Settings
        </button>
      </div>
    );
  }

  return (
    <div>
      <div>
        <h1 className="text-foreground text-2xl font-bold tracking-tight">
          {t('pageTitle')}
        </h1>
        <p className="text-muted-foreground mt-1 text-sm">{t('pageDesc')}</p>
      </div>

      <div className="mt-6 grid gap-6 lg:grid-cols-[236px_minmax(0,1fr)] lg:items-start">
        <SettingsRail active={section} onSelect={go} hints={hints} />
        <div className="min-w-0">{panel[section]}</div>
      </div>
    </div>
  );
}

import { NextResponse } from 'next/server';
import { requireApiKey } from '@/lib/auth/api-context'; // wait, for dashboard routes we usually use try/catch -> toErrorResponse with getCurrentAccount.
// Let's look at `src/app/api/account/route.ts` pattern.
import { getCurrentAccount } from '@/lib/auth/account';
import { createClient } from '@/lib/supabase/server';
import { hasMinRole } from '@/lib/auth/roles';
import { toApiErrorResponse } from '@/lib/api/v1/respond';

export async function GET(request: Request) {
  try {
    const account = await getCurrentAccount();
    if (!account)
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

    // Check permission - S3 says admin+ only
    if (!hasMinRole(account.role, 'admin')) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const supabase = await createClient();
    const { data, error } = await supabase
      .from('lead_routing_rules')
      .select('*')
      .eq('account_id', account.accountId)
      .order('priority', { ascending: true });

    if (error) throw error;
    return NextResponse.json({ routing_rules: data });
  } catch (error) {
    return toApiErrorResponse(error);
  }
}

export async function POST(request: Request) {
  try {
    const account = await getCurrentAccount();
    if (!account)
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

    if (!hasMinRole(account.role, 'admin')) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const body = await request.json();
    const supabase = await createClient();

    // Using service-role or user-client? The migration sets RLS so user client is fine.
    // wait, supabaseServer is the user client.

    const { data, error } = await supabase
      .from('lead_routing_rules')
      .insert({
        account_id: account.accountId,
        priority: body.priority ?? 0,
        condition_type: body.condition_type,
        condition_value: body.condition_value,
        action_type: body.action_type,
        action_value: body.action_value,
        is_active: body.is_active ?? true,
      })
      .select()
      .single();

    if (error) throw error;
    return NextResponse.json(data);
  } catch (error) {
    return toApiErrorResponse(error);
  }
}

