      return NextResponse.json(
        { error: 'No active subscription found.' },
        { status: 400 }
      );
    }

    const baseUrl = process.env.NEXT_PUBLIC_SITE_URL || 'http://localhost:3000';

    const session = await stripe.billingPortal.sessions.create({
      customer: account.stripe_customer_id,
      return_url: `${baseUrl}/settings`,
    });

    return NextResponse.json({ url: session.url }, { status: 200 });
  } catch (err) {
    console.error('[billing/portal] error:', err);
    return NextResponse.json(
      { error: err instanceof Error ? err.message : String(err) },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import {
  getCurrentAccount,
  requireRole,
  toErrorResponse,
} from '@/lib/auth/account';
import { supabaseAdmin } from '@/lib/automations/admin-client';

export async function GET(request: Request) {
  try {
    const ctx = await requireRole('admin');
    const url = new URL(request.url);
    const unassigned = url.searchParams.get('unassigned') === 'true';

    let query = ctx.supabase
      .from('contacts')
      .select('*, conversations(status, assigned_agent_id)')
      .eq('account_id', ctx.accountId)
      .order('created_at', { ascending: false });

    if (unassigned) {
      // Supabase direct filter for nested array can be tricky.
      // We will fetch and filter in memory, or use a better query.
      // Better to fetch up to 100 recent and filter, or use an inner join.
      query = ctx.supabase
        .from('contacts')
        .select(
          '*, conversations(status, assigned_agent_id), lead_details(source)'
        )
        .eq('account_id', ctx.accountId)
        .order('created_at', { ascending: false })
        .limit(200);
    }

    const { data, error } = await query;

    if (error) {
      console.error('[GET /api/contacts] error:', error);
      return NextResponse.json(
        { error: 'Failed to fetch contacts' },
        { status: 500 }
      );
    }

    let results = data;
    if (unassigned) {
      results = data.filter(
        (c: {
          conversations?:
            | { status?: string; assigned_agent_id?: string | null }
            | { status?: string; assigned_agent_id?: string | null }[];
        }) => {
          const convs = Array.isArray(c.conversations)
            ? c.conversations
            : c.conversations
              ? [c.conversations]
              : [];
          const openConv = convs.find((conv) => conv.status === 'open');
          return !openConv || openConv.assigned_agent_id === null;
        }
      );
    }

    return NextResponse.json({ contacts: results });
  } catch (err) {
    return toErrorResponse(err);
  }
}

import { NextResponse } from 'next/server';
import { requireRole, toErrorResponse } from '@/lib/auth/account';

export async function GET(request: Request) {
  try {
    const ctx = await requireRole('admin');

    // Query deals grouped by stage and join pipeline_stages
    const { data: deals, error: dErr } = await ctx.supabase
      .from('deals')
      .select('stage_id, pipeline_stages!deals_stage_id_fkey(name, position)')
      .eq('account_id', ctx.accountId)
      .eq('status', 'open'); // Assuming we only want the funnel for open deals

    if (dErr) {
      console.error('[GET /api/dashboard/pipeline-funnel] error:', dErr);
      return NextResponse.json(
        { error: 'Failed to fetch deals' },
        { status: 500 }
      );
    }

    const stageCounts = new Map<
      string,
      { name: string; position: number; count: number }
    >();

    for (const d of deals || []) {
      if (!d.pipeline_stages) continue;

      const stage = Array.isArray(d.pipeline_stages)
        ? d.pipeline_stages[0]
        : d.pipeline_stages;
      const key = d.stage_id;

      if (!stageCounts.has(key)) {
        stageCounts.set(key, {
          name: stage.name,
          position: stage.position,
          count: 0,
        });
      }
      const existing = stageCounts.get(key)!;
      existing.count += 1;
    }

    // pipeline_stages has no account_id — filter via pipelines join
    const { data: allStages, error: sErr } = await ctx.supabase
      .from('pipeline_stages')
      .select('id, name, position, pipelines!inner(account_id)')
      .eq('pipelines.account_id', ctx.accountId)
      .order('position', { ascending: true });

    if (sErr) throw sErr;

    const funnel = (allStages || []).map((s) => {
      const count = stageCounts.get(s.id)?.count || 0;
      return { stage: s.name, count };
    });

    return NextResponse.json({ funnel });
  } catch (err) {
    return toErrorResponse(err);
  }
}

import { NextResponse } from 'next/server';
import { getCurrentAccount } from '@/lib/auth/account';
import { createClient } from '@/lib/supabase/server';
import { hasMinRole } from '@/lib/auth/roles';

export async function GET() {
  try {
    const account = await getCurrentAccount();
    if (!account)
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

    if (!hasMinRole(account.role, 'admin')) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const supabase = await createClient();
    const { data: deals, error } = await supabase
      .from('deals')
      .select(
        `
        id,
        title,
        value,
        currency,
        status,
        expected_close_date,
        pipeline_stages ( name ),
        contacts ( name, email, phone )
      `
      )
      .eq('account_id', account.accountId)
      .order('created_at', { ascending: false });

    if (error) throw error;

    const csvRows = [
      'ID,Title,Value,Currency,Status,Stage,Expected Close,Contact Name,Contact Email,Contact Phone',
    ];

    for (const deal of deals || []) {
      const stage = Array.isArray(deal.pipeline_stages)
        ? deal.pipeline_stages[0]?.name
        : (deal.pipeline_stages as Record<string, unknown> | null)?.name;
      const contact = Array.isArray(deal.contacts)
        ? deal.contacts[0]
        : (deal.contacts as Record<string, unknown> | null);

      csvRows.push(
        [
          deal.id,
          `"${deal.title?.replace(/"/g, '""') || ''}"`,
          deal.value || 0,
          deal.currency || '',
          deal.status || '',
          `"${stage?.replace(/"/g, '""') || ''}"`,
          deal.expected_close_date || '',
          `"${contact?.name?.replace(/"/g, '""') || ''}"`,
          `"${contact?.email?.replace(/"/g, '""') || ''}"`,
          `"${contact?.phone?.replace(/"/g, '""') || ''}"`,
        ].join(',')
      );
    }

    const csvString = csvRows.join('\n');

    return new NextResponse(csvString, {
      headers: {
        'Content-Type': 'text/csv',
        'Content-Disposition': 'attachment; filename="deals_export.csv"',
      },
    });
  } catch (_error) {
    return NextResponse.json(
      { error: 'Failed to export deals' },
      { status: 500 }
    );
  }
}

