              <CardDescription className="text-muted-foreground">
                {t('apiCredentialsDesc')}
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <Label className="text-muted-foreground">
                  {t('phoneNumberId')}
                </Label>
                <Input
                  placeholder={t('phoneNumberIdPlaceholder')}
                  value={phoneNumberId}
